Object.assign(window.TEM8_DICTIONARY, {"admiration":{"media":{"uk":"media/uk/admiration__gb_1.mp3","us":"media/us/admiration__us_1.mp3"},"oxford":{"phon":"ˌædməˈreɪʃn","pos":"noun","senses":[{"en":"a feeling of respect for and approval of somebody/something","cn":"钦佩；赞赏；羡慕","ex":{"en":"He never lost the admiration of his students.","cn":"他从未失去学生对他的尊敬。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"钦佩；羡慕；赞赏","en":"Admiration is a feeling of great liking and respect for a person or thing.","ex":{"en":"I have always had the greatest admiration for him","cn":"我始终对他最为钦佩。"}}]},"examples":[{"en":"I have great admiration for her as a writer.","cn":"我十分钦佩她这个作家。"},{"en":"to watch/gaze in admiration","cn":"赞赏地观看/凝视着"}]},"admit":{"media":{"uk":"media/uk/admit__gb_1.mp3","us":"media/us/admit__us_1.mp3"},"oxford":{"phon":"ədˈmɪt","pos":"verb","senses":[{"en":"to agree, often unwillingly, that something is true","cn":"（常指勉强）承认","g":"[intransitive, transitive]","sc":"accept truth","ex":{"en":"It was a stupid thing to do, I admit.","cn":"我承认，那次干的是件蠢事。"}},{"en":"to say that you have done something wrong or illegal","cn":"承认（过错、罪行）；招认；招供","g":"[intransitive, transitive]","sc":"accept blame","ex":{"en":"He refused to admit to the other charges.","cn":"他拒不承认其他指控。"}},{"en":"to allow somebody/something to enter a place","cn":"准许…进入（某处）","g":"[transitive]","lab":"formal","sc":"allow to enter/join","ex":{"en":"Each ticket admits one adult.","cn":"每张票只准许一位成人入场。"}},{"en":"to allow somebody to become a member of a club, a school or an organization","cn":"准许…加入（俱乐部、组织）；接收（入学）","g":"[transitive]","lab":"formal","sc":"allow to enter/join","ex":{"en":"The society admits all US citizens over 21.","cn":"凡 21 岁以上的美国公民均可加入该社团。"}},{"en":"to take somebody to a hospital or other institution where they can receive special care","cn":"接收入院（或收容所等）；收治","g":"[transitive, often passive]","lab":"formal","sc":"to hospital","ex":{"en":"Two crash victims were admitted to the local hospital.","cn":"两位车祸受害者已送进当地医院。"}},{"en":"to accept that evidence is legally valid and can be presented in court","cn":"承认：接受证据在法律上有效并且可以在法庭上提出","g":"[transitive]","lab":"formal","sc":"evidence","ex":{"en":"Judge Neilson refused to admit the evidence because it had been illegally obtained.","cn":"尼尔森法官拒绝承认这些证据，因为这些证据是非法获得的。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（常指不情愿地）承认，供认","en":"If you admit that something bad, unpleasant, or embarrassing is true, you agree, often unwillingly, that it is true.","ex":{"en":"I am willing to admit that I do make mistakes","cn":"我愿意承认我确实会犯错。"}},{"pos":"VERB 动词","cn":"接受（入院）；收治","en":"If someone is admitted to hospital, they are taken into hospital for treatment and kept there until they are well enough to go home.","ex":{"en":"She was admitted to hospital with a soaring temperature","cn":"她因发高烧被送进医院。"}},{"pos":"VERB 动词","cn":"准许…加入；接纳；招收","en":"If someone is admitted to an organization or group, they are allowed to join it.","ex":{"en":"He was admitted to the Academie Culinaire de France","cn":"他获准加入法兰西厨艺学会。"}},{"pos":"VERB 动词","cn":"准许…进入","en":"To admit someone to a place means to allow them to enter it.","ex":{"en":"Embassy security personnel refused to admit him or his wife","cn":"使馆保安人员不允许他和夫人进入。"}}]},"examples":[{"en":"I couldn't admit to my parents that I was finding the course difficult.","cn":"我无法向父母实话实说，我觉得这门课程很难。"},{"en":"The society admits all US citizens over 21.","cn":"凡 21 岁以上的美国公民均可加入该社团。"}]},"advertisement":{"oxford":{"phon":"ədˈvɜːtɪsmənt","pos":"noun","senses":[{"en":"a notice, picture or film telling people about a product, job or service","cn":"广告；启事","g":"[countable]","lab":"informal","ex":{"en":"a newspaper/television advertisement","cn":"报纸／电视广告"}},{"en":"an example of something that shows its good qualities","cn":"广告（样）品","g":"[countable]","lab":"British English also","ex":{"en":"Dirty streets and homelessness are no advertisement for a prosperous society.","cn":"肮脏的街道和无家可归现象绝不是繁荣社会的景象。"}},{"en":"the act of advertising something and making it public","cn":"广告活动；广告宣传","g":"[uncountable]","ex":{"en":"We are employing an assistant to help with the advertisement of the group’s activities.","cn":"我们打算招聘一名助手来做团队活动的宣传工作。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"广告;公告;启事","en":"An advertisement is an announcement in a newspaper, on television, or on a poster about something such as a product, event, or job.","ex":{"en":"Miss Parrish recently placed an advertisement in the local newspaper.","cn":"帕里什小姐最近在本埠报纸上登了一则广告。"}},{"pos":"N-COUNT 可数名词","cn":"（某一类事物的）活广告","en":"If you say that an example of something is an advertisement for that thing in general, you mean that it shows how good that thing is.","ex":{"en":"The England team were a poor advertisement for European football tonight","cn":"英格兰队今晚为欧洲足球做了一次糟糕的宣传。"}}]},"media":{"uk":"media/uk/advertisement__gb_1.mp3","us":"media/us/advertisement__us_1.mp3"},"examples":[{"en":"Dirty streets and homelessness are no advertisement for a prosperous society.","cn":"肮脏的街道和无家可归现象绝不是繁荣社会的景象。"},{"en":"Put an advertisement in the local paper to sell your car.","cn":"在当地报纸登一则广告来出售你的汽车。"}]},"admire":{"media":{"uk":"media/uk/admire__gb_1.mp3","us":"media/us/admire__us_1.mp3"},"oxford":{"phon":"ədˈmaɪə(r)","pos":"verb","senses":[{"en":"to respect somebody for what they have done or to respect their qualities","cn":"钦佩；赞赏；仰慕","ex":{"en":"I really admire your enthusiasm.","cn":"我确实钦佩你的热情。"}},{"en":"to look at something and think that it is attractive and/or impressive","cn":"欣赏","ex":{"en":"He stood back to admire his handiwork.","cn":"他退后几步欣赏他的手工制品。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"钦佩；欣赏；羡慕","en":"If you admire someone or something, you like and respect them very much.","ex":{"en":"I admired her when I first met her and I still think she's marvellous","cn":"初次见面时，我就非常佩服她，时至今日我仍然认为她很出色。"}},{"pos":"VERB 动词","cn":"欣赏；观赏","en":"If you admire someone or something, you look at them with pleasure.","ex":{"en":"We took time to stop and admire the view.","cn":"我们特意驻足欣赏风景。"}}]},"examples":[{"en":"I don't agree with her, but I admire her for sticking to her principles.","cn":"我不同意她的意见，但是我赞赏她恪守原则。"},{"en":"You have to admire the way he handled the situation.","cn":"你不得不佩服他处理这个局面的手段。"}]},"adversarial":{"oxford":{"phon":"ˌædvəˈseəriəl","pos":"adjective","senses":[{"en":"involving people who are in opposition and who argue against each other","cn":"对立的；敌对的","ex":{"en":"the adversarial nature of the two-party system","cn":"两党制的对抗本质"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"对立的；敌对的","en":"If you describe something as adversarial, you mean that it involves two or more people or organizations who are opposing each other.","ex":{"en":"In our country there is an adversarial relationship between government and business.","cn":"在我国，官商之间存在一种对立关系。"}}]},"media":{"uk":"media/uk/adversarial__gb_1.mp3","us":"media/us/adversarial__us_1.mp3"},"examples":[{"en":"the adversarial nature of the two-party system","cn":"两党制的对抗性"},{"en":"an adversarial system of justice","cn":"审判对抗制"}]},"additive":{"media":{"uk":"media/uk/additive__gb_1.mp3","us":"media/us/additive__us_1.mp3"},"oxford":{"phon":"ˈædətɪv","pos":"noun","senses":[{"en":"a substance that is added in small amounts to something, especially food, in order to improve it, give it colour, make it last longer, etc.","cn":"（尤指食品的）添加剂，添加物","lab":"British English","ex":{"en":"food additives","cn":"食品添加剂"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"添加物;添加剂","en":"An additive is a substance which is added in small amounts to foods or other things in order to improve them or to make them last longer.","ex":{"en":"Strict safety tests are carried out on food additives.","cn":"对食品添加剂进行了严格的安全检测。"}}]},"examples":[{"en":"chemical additives in petrol","cn":"汽油中的化学添加剂"},{"en":"additive-free orange juice","cn":"不含添加剂的橙汁"}]},"advice":{"media":{"uk":"media/uk/advice__gb_1.mp3","us":"media/us/advice__us_1.mp3"},"oxford":{"phon":"ədˈvaɪs","pos":"noun","senses":[{"en":"an opinion or a suggestion about what somebody should do in a particular situation","cn":"劝告；忠告；建议；意见","ex":{"en":"expert/practical/professional/medical advice","cn":"专家意见；实用性建议；专业意见；医嘱"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"劝告;忠告;意见","en":"If you give someone advice, you tell them what you think they should do in a particular situation.","ex":{"en":"Don't be afraid to ask for advice about ordering the meal","cn":"点餐时可以大胆征求意见。"}},{"pos":"PHRASE 短语","cn":"听取律师的意见;咨询律师","en":"If you take advice or take legal advice, you ask a lawyer for his or her professional opinion on a situation.","ex":{"en":"We are taking advice on legal steps to recover the money","cn":"我们正在就追回该款项所需的法律程序咨询律师。"}}]},"examples":[{"en":"They give advice to people with HIV and AIDS.","cn":"他们向艾滋病病毒携带者和艾滋病患者提供咨询。"},{"en":"Ask your teacher 's advice / Ask your teacher for advice on how to prepare for the exam.","cn":"向你的老师咨询一下如何准备考试。"}]},"advertising":{"media":{"uk":"media/uk/advertising__gb_1.mp3","us":"media/us/advertising__us_1.mp3"},"oxford":{"phon":"ˈædvətaɪzɪŋ","pos":"noun","senses":[{"en":"the activity and industry of advertising things to people on television, in newspapers, on the internet, etc.","cn":"广告活动；广告业；做广告","ex":{"en":"Cigarette advertising has been banned.","cn":"香烟广告已遭禁止。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"广告活动;做广告","en":"Advertising is the activity of creating advertisements and making sure people see them."}]},"examples":[{"en":"A good advertising campaign will increase our sales.","cn":"良好的广告宣传活动会增加我们的销售量。"},{"en":"Val works for an advertising agency (= a company that designs advertisements).","cn":"瓦尔为一家广告公司工作。"}]},"adventure":{"media":{"uk":"media/uk/adventure__gb_1.mp3","us":"media/us/adventure__us_1.mp3"},"oxford":{"phon":"ədˈventʃə(r)","pos":"noun","senses":[{"en":"an unusual, exciting or dangerous experience, journey or series of events","cn":"冒险；冒险经历；奇遇","g":"[countable]","ex":{"en":"her adventures travelling in Africa","cn":"她在非洲旅行时的冒险经历"}},{"en":"the quality of being excited and willing to take risks, try new ideas, etc.","cn":"冒险精神；大胆开拓","g":"[uncountable]","ex":{"en":"a sense/spirit of adventure","cn":"冒险意识／精神"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"冒险；冒险经历；奇遇","en":"If someone has an adventure, they become involved in an unusual, exciting, and rather dangerous journey or series of events.","ex":{"en":"I set off for a new adventure in the United States on the first day of the new year.","cn":"新年第一天，我在美国开始了一次新的冒险。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"冒险的刺激；大胆的开拓；勇敢的闯荡","en":"Adventure is excitement and willingness to do new, unusual, or rather dangerous things.","ex":{"en":"Their cultural backgrounds gave them a spirit of adventure.","cn":"他们的文化背景赋予了他们一种冒险精神。"}},{"pos":"VERB 动词","cn":"去（某地）探险","en":"If you adventure somewhere, you go somewhere new, unusual, and exciting.","ex":{"en":"The group has adventured as far as the Austrian alps.","cn":"该队伍的探险之旅远至奥地利的阿尔卑斯山。"}}]},"examples":[{"en":"When you're a child, life is one big adventure.","cn":"在孩提时代，生活是一大不寻常的经历。"},{"en":"her adventures travelling in Africa","cn":"她在非洲旅行时的冒险经历"}]},"adverbs":{"oxford":{"phon":"ˈædvɜːb","pos":"noun","senses":[{"en":"a word that adds more information about place, time, manner, cause or degree to a verb, an adjective, a phrase or another adverb","cn":"副词"}]}},"adaptive":{"oxford":{"phon":"əˈdæptɪv","pos":"adjective","senses":[{"en":"connected with changing; able to change when necessary in order to deal with different situations","cn":"适应的；有适应能力的","ex":{"en":"Adaptive learning systems offer students customized learning experiences according to their needs and capabilities.","cn":"适应性学习系统根据学生的需要和能力为他们提供个性化的学习体验。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"适应的；有适应能力的","en":"Adaptive means having the ability or tendency to adapt to different situations.","ex":{"en":"Societies need to develop highly adaptive behavioural rules for survival.","cn":"社会需要发展具有高度适应性的生存行为规则。"}}]},"media":{"uk":"media/uk/adaptive__gb_1.mp3","us":"media/us/adaptive__us_1.mp3"}},"advisable":{"media":{"uk":"media/uk/advisable__gb_1.mp3","us":"media/us/advisable__us_1.mp3"},"oxford":{"phon":"ədˈvaɪzəbl","pos":"adjective","senses":[{"en":"sensible and a good idea in order to achieve something","cn":"明智；可取","ex":{"en":"Early booking is advisable.","cn":"预订宜早。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可取的；明智的；适当的","en":"If you tell someone that it is advisable to do something, you are suggesting that they should do it, because it is sensible or is likely to achieve the result they want.","ex":{"en":"Because of the popularity of the region, it is advisable to book hotels or camp sites in advance","cn":"鉴于该地区很受人们青睐，最好提前预订旅馆或宿营地。"}}]},"examples":[{"en":"Early booking is advisable.","cn":"预订宜早。"},{"en":"It is advisable to book early.","cn":"预订宜早。"}]},"adolescence":{"media":{"uk":"media/uk/adolescence__gb_1.mp3","us":"media/us/adolescence__us_1.mp3"},"oxford":{"phon":"ˌædəˈlesns","pos":"noun","senses":[{"en":"the time in a person’s life when they develop from a child into an adult","cn":"青春期","lab":"often ironic) 102／23 （） 102／23 （）","ex":{"en":"Adolescence brings about major changes in a young person’s body.","cn":"在青春期时身体会发生很大变化。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"青春期","en":"Adolescence is the period of your life in which you develop from being a child into being an adult.","ex":{"en":"Some people become very self-conscious in adolescence.","cn":"有些人在青春期会变得异常害羞。"}}]}},"adopted":{"media":{"uk":"media/uk/adopted__gb_1.mp3","us":"media/us/adopted__us_1.mp3"},"oxford":{"phon":"əˈdɒptɪd","pos":"adjective","senses":[{"en":"an adopted child has legally become part of a family that is not the one in which they were born","cn":"收养的；领养的","ex":{"en":"Danny is their adopted son.","cn":"丹尼是他们的养子。"}},{"en":"an adopted country is one in which somebody chooses to live although it is not the one they were born in","cn":"所选择居住的；移居的"}]},"examples":[{"en":"Danny is their adopted son.","cn":"丹尼是他们的养子。"},{"en":"his adopted son","cn":"他的养子"}]},"additional":{"media":{"uk":"media/uk/additional__gb_1.mp3","us":"media/us/additional__us_1.mp3"},"oxford":{"phon":"əˈdɪʃənl","pos":"adjective","senses":[{"en":"more than was first mentioned or is usual","cn":"附加的；额外的；外加的","ex":{"en":"additional resources/funds/security/funding/costs","cn":"额外资源；追加经费；外加保安措施；额外资金／成本"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"额外的;附加的;添加的","en":"Additional things are extra things apart from the ones already present.","ex":{"en":"The US is sending additional troops to the region","cn":"美国正向该地区增兵。"}}]},"examples":[{"en":"The government provided an additional £25 million to expand the service.","cn":"政府另拨了 2 500 万英镑用于扩展该服务。"},{"en":"Additionally, the bus service will run on Sundays, every two hours.","cn":"此外，公共汽车将于星期天运行，每两小时一班。"}]},"adopts":{"oxford":{"phon":"əˈdɒpt","pos":"verb","senses":[{"en":"to take sb else's child into your family and become its legal parent(s)","cn":"收养；领养"},{"en":"to start to use a particular method or to show a particular attitude towards sb/sth","cn":"采用（某方法）；采取（某态度）"}]},"media":{"uk":"media/uk/adopt__gb_1.mp3","us":"media/us/adopt__us_1.mp3"}},"advertisements":{"oxford":{"phon":"ədˈvɜːtɪsmənt","pos":"noun","senses":[{"en":"a notice, picture or film telling people about a product, job or service","cn":"广告；启事"},{"en":"an example of sth that shows its good qualities","cn":"广告（样）品"}]}},"adjectives":{"oxford":{"phon":"ˈædʒɪktɪv","pos":"noun","senses":[{"en":"a word that describes a person or thing, for example big , red and clever in a big house , red wine and a clever idea","cn":"形容词"}]}},"add":{"media":{"uk":"media/uk/add__gb_1.mp3","us":"media/us/add__us_1.mp3"},"oxford":{"phon":"æd","pos":"verb","senses":[{"en":"to put something together with something else so as to increase the size, number, amount, etc.","cn":"增加；添加","g":"[transitive]","ex":{"en":"Next add the flour.","cn":"接着加面粉。"}},{"en":"to put numbers or amounts together to get a total","cn":"加","g":"[intransitive, transitive]","ex":{"en":"He knew how to add and subtract.","cn":"他知道如何做加减法。"}},{"en":"to say something more; to make a further remark","cn":"补充说；继续说","g":"[transitive]","ex":{"en":"‘And don't be late,’ she added.","cn":"“还有别迟到。”她补充说道。"}},{"en":"to give a particular quality to an event, a situation, etc.","cn":"添加（特色）","g":"[transitive]","ex":{"en":"The suite will add a touch of class to your bedroom.","cn":"这套家具会给你的卧室增添一些典雅气质。"}},{"en":"attention deficit disorder","cn":"注意障碍","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"添加；增加；掺加","en":"If you add one thing to another, you put it in or on the other thing, to increase, complete, or improve it.","ex":{"en":"Add the grated cheese to the sauce","cn":"把磨碎的干酪加到调味汁里。"}},{"pos":"VERB 动词","cn":"加","en":"If you add numbers or amounts together, you calculate their total.","ex":{"en":"Banks add all the interest and other charges together","cn":"银行合计所有利息和其他费用。"}},{"pos":"VERB 动词","cn":"增添；增加","en":"If one thing adds to another, it makes the other thing greater in degree or amount.","ex":{"en":"This latest incident will add to the pressure on the government","cn":"最近的这次事件将会给政府增加压力。"}},{"pos":"VERB 动词","cn":"增加，增添（特色）","en":"To add a particular quality to something means to cause it to have that quality.","ex":{"en":"The generous amount of garlic adds flavour","cn":"蒜多了能提味。"}},{"pos":"VERB 动词","cn":"补充说;进一步说","en":"If you add something when you are speaking, you say something more.","ex":{"en":"'You can tell that he is extremely embarrassed,' Mr Brigden added","cn":"“你能看出他尴尬极了，”布里格登先生补充道。"}},{"pos":"PHRASE 短语","cn":"另外；再者","en":"You use added to this or added to that to introduce a fact that supports or widens what you are saying.","ex":{"en":"More than 750 commercial airliners were involved in fatal accidents last year. Added to that were the 1,550 smaller aircraft.","cn":"去年750多家商业航空公司遭遇过人员死亡的事故。另外还有1,550架小型飞机也出过同样的事故。"}},{"pos":"","cn":"","en":"to add insult to injury→see: ;"},{"pos":"","cn":"","en":"相关词组：add in add on add up add up to"}]},"examples":[{"en":"Add to this the excellent service and you can see why it's the most popular hotel on the island.","cn":"这再加上优质服务，你就能明白为何这家旅馆在岛上最受欢迎。"},{"en":"The plan has the added (= extra) advantage of bringing employment to rural areas.","cn":"该计划还有一个优点，就是给农村地区带来了就业机会。"}]},"adhered":{"oxford":{"phon":"ədˈhɪə(r)","pos":"verb","senses":[{"en":"( formal ) to stick firmly to sth","cn":"粘附；附着"},{"en":"( formal ) to behave according to a particular law, rule, set of instructions, etc; to follow a particular set of beliefs or a fixed way of doing sth","cn":"坚持，遵守，遵循（法律、规章、指示、信念等）"}]}},"advising":{"oxford":{"phon":"ədˈvaɪz","pos":"verb","senses":[{"en":"to tell sb what you think they should do in a particular situation","cn":"劝告；忠告；建议"},{"en":"to give sb help and information on a subject that you know a lot about","cn":"出主意；提出建议；提供咨询"}]}},"addresses":{"oxford":{"phon":"əˈdres","pos":"noun","senses":[{"en":"details of where sb lives or works and where letters, etc. can be sent","cn":"住址；地址；通信处"},{"en":"( computing","cn":"计 ) a series of words and symbols that tells you where you can find sth using a computer, for example on the Internet （互"}]},"media":{"uk":"media/uk/address__gb_1.mp3","us":"media/us/address__us_3.mp3"}},"admits":{"oxford":{"phon":"ədˈmɪt","pos":"verb","senses":[{"en":"to agree, often unwillingly, that sth is true （","cn":"常指勉强）承认"},{"en":"to say that you have done sth wrong or illegal","cn":"承认（过错、罪行）；招认；招供"}]},"media":{"uk":"media/uk/admit__gb_1.mp3","us":"media/us/admit__us_1.mp3"}},"addressed":{"oxford":{"phon":"əˈdres","pos":"noun","senses":[{"en":"details of where sb lives or works and where letters, etc. can be sent","cn":"住址；地址；通信处"},{"en":"( computing","cn":"计 ) a series of words and symbols that tells you where you can find sth using a computer, for example on the Internet （互"}]},"media":{"uk":"media/uk/address__gb_1.mp3","us":"media/us/address__us_3.mp3"}},"advises":{"oxford":{"phon":"ədˈvaɪz","pos":"verb","senses":[{"en":"to tell sb what you think they should do in a particular situation","cn":"劝告；忠告；建议"},{"en":"to give sb help and information on a subject that you know a lot about","cn":"出主意；提出建议；提供咨询"}]}},"adjustment":{"media":{"uk":"media/uk/adjustment__gb_1.mp3","us":"media/us/adjustment__us_1.mp3"},"oxford":{"phon":"əˈdʒʌstmənt","pos":"noun","senses":[{"en":"a small change made to something in order to correct or improve it","cn":"调整；调节","ex":{"en":"I've made a few adjustments to the design.","cn":"我已对设计作了几处调整。"}},{"en":"a change in the way a person behaves or thinks","cn":"（行为、思想的）调整，适应","ex":{"en":"She went through a period of emotional adjustment after her marriage broke up.","cn":"婚姻破裂后，她熬过了一段感情调整期。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"调整；校正；校准","en":"An adjustment is a small change that is made to something such as a machine or a way of doing something.","ex":{"en":"Compensation could be made by adjustments to taxation","cn":"通过调整税收可以作出补偿。"}},{"pos":"N-COUNT 可数名词","cn":"（行为或思想的）调整，转变","en":"An adjustment is a change in a person's behaviour or thinking.","ex":{"en":"He will have to make major adjustments to his thinking if he is to survive in office.","cn":"要想保住这份工作，他就必须在观念上作出重大的转变。"}}]},"examples":[{"en":"She went through a period of emotional adjustment after her marriage broke up.","cn":"婚姻破裂后，她熬过了一段感情调整期。"},{"en":"I've made a few adjustments to the design.","cn":"我已对设计作了几处调整。"}]},"addictive":{"media":{"uk":"media/uk/addictive__gb_1.mp3","us":"media/us/addictive__us_1.mp3"},"oxford":{"phon":"əˈdɪktɪv","pos":"adjective","senses":[{"en":"if a substance or activity is addictive, it makes people unable to stop using it or doing it","cn":"使人上瘾的","ex":{"en":"Heroin is highly addictive.","cn":"海洛因很容易使人上瘾。"}},{"en":"easily becoming addicted to something; showing this","cn":"易上瘾的","ex":{"en":"Some people have an addictive personality.","cn":"有些人容易对事物成瘾。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人成瘾的","en":"If a drug is addictive, people who take it cannot stop taking it.","ex":{"en":"Cigarettes are highly addictive","cn":"香烟很容易使人上瘾。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人着迷的","en":"Something that is addictive is so enjoyable that it makes you want to do it or have it a lot.","ex":{"en":"Video movie-making can quickly become addictive.","cn":"制作视频电影能很快让人入迷。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易着迷的；易上瘾的","en":"If someone has an addictive personality, they easily become addicted to something.","ex":{"en":"I have an eating disorder and an addictive personality.","cn":"我饮食没有规律，而且性格上容易沉迷某事。"}}]},"examples":[{"en":"I find jogging very addictive.","cn":"我觉得慢跑锻炼很使人着迷。"},{"en":"Heroin is highly addictive.","cn":"海洛因很容易使人上瘾。"}]},"addicted":{"oxford":{"phon":"əˈdɪktɪd","pos":"adjective","senses":[{"en":"unable to stop using or doing something as a habit, especially something harmful","cn":"成瘾的","ex":{"en":"to become addicted to drugs/gambling/social media","cn":"吸毒／赌博成瘾；沉迷于社交网络"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（吸毒）成瘾的，上瘾的","en":"Someone who is addicted to a harmful drug cannot stop taking it.","ex":{"en":"Many of the women are addicted to heroin and cocaine","cn":"这些女人中很多人都吸食海洛因和可卡因成瘾了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"入迷的;着迷的","en":"If you say that someone is addicted to something, you mean that they like it very much and want to spend as much time doing it as possible.","ex":{"en":"I went through about four years of being addicted to video games","cn":"我大约有4年时间沉迷在电子游戏中。"}}]},"media":{"uk":"media/uk/addicted__gb_1.mp3","us":"media/us/addicted__us_1.mp3"},"examples":[{"en":"He's addicted to computer games.","cn":"他迷上了电脑游戏。"},{"en":"to become addicted to drugs/gambling","cn":"吸毒成瘾；嗜赌"}]},"advance":{"media":{"uk":"media/uk/advance__gb_1.mp3","us":"media/us/advance__us_1.mp3"},"oxford":{"phon":"ədˈvɑːns","pos":"noun","senses":[{"en":"progress or a development in a particular activity or area of understanding","cn":"进步；进展","g":"[countable, uncountable]","sc":"development","ex":{"en":"We live in an age of rapid technological advance.","cn":"我们生活在技术迅猛发展的时代。"}},{"en":"the forward movement of a group of people, especially armed forces","cn":"（尤指武装部队的）前进，行进","g":"[countable]","sc":"forward movement","ex":{"en":"We feared that an advance on the capital would soon follow.","cn":"我们担心接下来会马上向首都推进。"}},{"en":"money paid for work before it has been done or money paid earlier than expected","cn":"预付款","g":"[countable, usually singular]","sc":"money","ex":{"en":"They offered an advance of £5 000 after the signing of the contract.","cn":"他们在合同签订后预付了 5 000 英镑。"}},{"en":"attempts to start a sexual relationship with somebody","cn":"勾引；求爱；追求","g":"[plural]","sc":"sexual","ex":{"en":"He had made advances to one of his students.","cn":"他曾追求过他的一个学生。"}},{"en":"an increase in the price or value of something","cn":"（价格、价值的）上涨，提高","g":"[countable]","lab":"business","sc":"price increase","ex":{"en":"Share prices showed significant advances.","cn":"股票价格大幅上涨。"}},{"en":"if knowledge, technology, etc. advances, it develops and improves","cn":"（知识、技术等）发展，进步","g":"[intransitive, transitive]","sc":"develop","ex":{"en":"Technology is advancing at an incredibly rapid pace.","cn":"技术进步的速度快得惊人。"},"pos":"verb"},{"en":"to move forward towards somebody/something, often in order to attack or threaten them or it","cn":"（为了进攻、威胁等）前进，行进","g":"[intransitive]","sc":"move forward","ex":{"en":"The troops were finally given the order to advance.","cn":"部队终于接到前进的命令。"},"pos":"verb"},{"en":"to help something to succeed","cn":"促进；推动","g":"[transitive]","sc":"help to succeed","ex":{"en":"Studying for new qualifications is one way of advancing your career.","cn":"为提高学历而进修是促进事业发展的一个办法。"},"pos":"verb"},{"en":"to give somebody money before the time it would usually be paid","cn":"预付","g":"[transitive]","sc":"money","ex":{"en":"We are willing to advance the money to you.","cn":"我们愿意预付款给你。"},"pos":"verb"},{"en":"to suggest an idea, a theory or a plan for other people to discuss","cn":"提出（想法、理论、计划）","g":"[transitive]","lab":"formal","sc":"suggest","ex":{"en":"The article advances a new theory to explain changes in the climate.","cn":"这篇文章提出了一个解释气候变化的新理论。"},"pos":"verb"},{"en":"to change the time or date of an event so that it takes place earlier","cn":"提前；提早","g":"[transitive]","lab":"formal","sc":"make earlier","ex":{"en":"The date of the trial has been advanced by one week.","cn":"审判日期提前了一星期。"},"pos":"verb"},{"en":"to move forward to a later part of something; to move something forward to a later part","cn":"向前推（至下一步）；（使）向前移动","g":"[intransitive, transitive]","lab":"formal","sc":"move forward","ex":{"en":"These players will now advance to the next round.","cn":"这些选手现在将进入下一轮。"},"pos":"verb"},{"en":"to increase in price or amount","cn":"上涨；增加","g":"[intransitive]","lab":"business","sc":"increase","ex":{"en":"Oil shares advanced amid economic recovery hopes.","cn":"在一片经济复苏的希望中石油股票价格上涨。"},"pos":"verb"},{"en":"done or given before something is going to happen","cn":"预先的；事先的","ex":{"en":"Please give us advance warning of any changes.","cn":"如有变动，请事先通知我们。"},"pos":"adjective"},{"en":"a group of people who go somewhere first, before the main group","cn":"先遣队；先头部队","ex":{"en":"The advance party for a winter ascent of Mount Everest has arrived in Nepal.","cn":"冬季攀登珠穆朗玛峰的先遣队已经抵达尼泊尔。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（常指为攻击而）前进，推进","en":"To advance means to move forward, often in order to attack someone.","ex":{"en":"Reports from Chad suggest that rebel forces are advancing on the capital","cn":"来自乍得的报告显示叛军正向首都推进。"}},{"pos":"VERB 动词","cn":"（尤指知识）发展，进步","en":"To advance means to make progress, especially in your knowledge of something.","ex":{"en":"Medical technology has advanced considerably","cn":"医学技术突飞猛进。"}},{"pos":"VERB 动词","cn":"贷给；预付；预支","en":"If you advance someone a sum of money, you lend it to them, or pay it to them earlier than arranged.","ex":{"en":"I advanced him some money, which he would repay on our way home","cn":"我先借给他一些钱，在我们回家的路上他会还给我的。"}},{"pos":"N-COUNT 可数名词","cn":"贷款;预付款","en":"An advance is money which is lent or paid to someone before they would normally receive it.","ex":{"en":"She was paid a £100,000 advance for her next two novels.","cn":"她接下来的两部小说得到了10万英镑的预付稿费。"}},{"pos":"VERB 动词","cn":"提前（未来事件的日期）；使（未来事件）提前发生","en":"To advance an event, or the time or date of an event, means to bring it forward to an earlier time or date.","ex":{"en":"Too much protein in the diet may advance the ageing process","cn":"饮食中摄入过量蛋白质可能会加速衰老。"}},{"pos":"VERB 动词","cn":"促进，推动（事业、利益或主张）；使加速","en":"If you advance a cause, interest, or claim, you support it and help to make it successful.","ex":{"en":"When not producing art of his own, Oliver was busy advancing the work of others.","cn":"奥利弗在不搞自己的艺术创作时，就会忙着帮助别人完成作品。"}},{"pos":"VERB 动词","cn":"提出（理论、论点）","en":"When a theory or argument is advanced, it is put forward for discussion.","ex":{"en":"Many theories have been advanced as to why some women suffer from depression","cn":"就一些女性患抑郁症的原因，各种说法纷至沓来。"}},{"pos":"N-VAR 可变名词","cn":"（常指军事行动中的）前进，行进，推进","en":"An advance is a forward movement of people or vehicles, usually as part of a military operation.","ex":{"en":"...an advance on enemy positions","cn":"向敌方阵地推进"}},{"pos":"N-PLURAL 复数名词","cn":"挑逗；勾引","en":"If you make advances to someone, you try to start a sexual relationship with them.","ex":{"en":"Mark had for some time been making advances towards her","cn":"马克追她已经有一段时间了。"}},{"pos":"N-VAR 可变名词","cn":"进步；进展","en":"An advance in a particular subject or activity is progress in understanding it or in doing it well.","ex":{"en":"Air safety has not improved since the dramatic advances of the 1970s","cn":"航空安全自从20世纪70年代得到显著提高之后，至今再没有任何改善。"}},{"pos":"N-SING 单数名词","cn":"改进；改善","en":"If something is an advance on what was previously available or done, it is better in some way.","ex":{"en":"This could be an advance on the present situation.","cn":"这样可能会改善当前状况。"}},{"pos":"ADJ 形容词","cn":"预先的；事先的","en":"Advance booking, notice, or warning is done or given before an event happens.","ex":{"en":"They don't normally give any advance notice about which building they're going to inspect","cn":"他们一般不会预先通知检查哪座大楼。"}},{"pos":"ADJ 形容词","cn":"先行的；先遣的","en":"An advance party or group is a small group of people who go on ahead of the main group.","ex":{"en":"The 20-strong advance party will be followed by another 600 soldiers as part of UN relief efforts.","cn":"作为联合国救援行动的一部分，在这支由20多人组成的先头部队之后还将增派600名士兵。"}},{"pos":"PREP-PHRASE 短语介词","cn":"在…的前面；在…之前","en":"If one thing happens or is done in advance of another, it happens or is done before the other thing.","ex":{"en":"I had asked everyone to submit questions in advance of the meeting.","cn":"我已请每个人在会议之前提交问题。"}},{"pos":"PHRASE 短语","cn":"提前;事先","en":"If you do something in advance, you do it before a particular date or event.","ex":{"en":"The subject of the talk is announced a week in advance.","cn":"会谈的主题已提前一周宣布。"}}]},"examples":[{"en":"They offered an advance of £5 000 after the signing of the contract.","cn":"他们在合同签订后预付了 5 000 英镑。"},{"en":"Studying for new qualifications is one way of advancing your career.","cn":"为提高学历而进修是促进事业发展的一个办法。"}]},"advancement":{"oxford":{"phon":"ədˈvɑːnsmənt","pos":"noun","senses":[{"en":"the process of helping something/somebody to make progress or succeed; the progress that is made","cn":"促进；推动；发展；前进","g":"[uncountable, countable]","ex":{"en":"the advancement of knowledge/education/science","cn":"知识／教育／科学的发展"}},{"en":"progress in a job, social class, etc.","cn":"（工作、社会阶级等的）提升，晋升","g":"[uncountable]","ex":{"en":"There are good opportunities for advancement if you have the right skills.","cn":"如果有合适的技能，就有很好的晋升机会。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"提升；晋升","en":"Advancement is progress in your job or in your social position.","ex":{"en":"He cared little for social advancement.","cn":"他不太在意社会地位的提升。"}},{"pos":"N-VAR 可变名词","cn":"促进;推动","en":"The advancement of something is the process of helping it to progress or the result of its progress.","ex":{"en":"..her work for the advancement of the status of women.","cn":"她为提高妇女地位所作的工作"}}]},"media":{"uk":"media/uk/advancement__gb_1.mp3","us":"media/us/advancement__us_1.mp3"},"examples":[{"en":"There are good opportunities for advancement if you have the right skills.","cn":"如果有合适的技能，就有很好的晋升机会。"},{"en":"the advancement of knowledge/education/science","cn":"知识/教育/科学的发展"}]},"adjective":{"oxford":{"phon":"ˈædʒɪktɪv","pos":"noun","senses":[{"en":"a word that describes a person or thing, for example big, blue and clever in a big house, blue sky and a clever idea","cn":"形容词","ex":{"en":"‘Reliable’ is not an adjective that could be applied to my car.","cn":"“可靠”这个形容词不适用于我的车。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"形容词","en":"An adjective is a word such as 'big', 'dead', or 'financial' that describes a person or thing, or gives extra information about them. Adjectives usually come before nouns or after link verbs."}]},"media":{"uk":"media/uk/adjective__gb_1.mp3","us":"media/us/adjective__us_1.mp3"},"examples":[{"en":"In ‘bread knife’, the word ‘bread’ is used adjectivally.","cn":"在词组 bread knife 中，bread 用作形容词。"},{"en":"an adjectival phrase","cn":"形容词短语"}]},"adversary":{"media":{"uk":"media/uk/adversary__gb_1.mp3","us":"media/us/adversary__us_1.mp3"},"oxford":{"phon":"ˈædvəsəri","pos":"noun","senses":[{"en":"a person that somebody is opposed to and competing with in an argument or a battle","cn":"（辩论、战斗中的）敌手，对手","ex":{"en":"his old political adversary","cn":"他的老政治对手"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"敌手；对手","en":"Your adversary is someone you are competing with, or arguing or fighting against.","ex":{"en":"Elliott crossed the finish line just half a second behind his adversary","cn":"埃利奥特跨过终点线时仅比对手落后半秒钟。"}}]},"examples":[{"en":"his old adversary","cn":"他的老对手"}]},"advantage":{"media":{"uk":"media/uk/advantage__gb_1.mp3","us":"media/us/advantage__us_1.mp3"},"oxford":{"phon":"ədˈvɑːntɪdʒ","pos":"noun","senses":[{"en":"a thing that helps you to be better or more successful than other people","cn":"有利条件；有利因素；优势","ex":{"en":"a distinct/significant/huge advantage","cn":"明显的／显著的／巨大的优势"}},{"en":"a quality of something that makes it better or more useful","cn":"优点","ex":{"en":"Each of these systems has its advantages and disadvantages.","cn":"这些系统各有其优缺点。"}},{"en":"the first point scored after a score of 40–40","cn":"（局末平分后）占先；优势分","g":"[uncountable]","ex":{"en":"Advantage Miss Stephens.","cn":"斯蒂芬斯小姐占先。"}},{"en":"to put somebody in a better position than other people or than they were in before","cn":"使处于有利地位；有利于；有助于","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"有利条件；有利因素；优势","en":"An advantage is something that puts you in a better position than other people.","ex":{"en":"They are deliberately flouting the law in order to obtain an advantage over their competitors","cn":"他们为了和竞争对手抢夺先机而公然无视法律。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"优势；有利地位","en":"Advantage is the state of being in a better position than others who are competing against you.","ex":{"en":"Men have created a social and economic position of advantage for themselves over women.","cn":"男性已经为自己创造了优于女性的社会和经济上的有利地位。"}},{"pos":"N-COUNT 可数名词","cn":"好处；益处；优点","en":"An advantage is a way in which one thing is better than another.","ex":{"en":"The great advantage of home-grown oranges is their magnificent flavour","cn":"家产柑橘的一大好处是口感极佳。"}},{"pos":"PHRASE 短语","cn":"利用","en":"If you take advantage of something, you make good use of it while you can.","ex":{"en":"I intend to take full advantage of this trip to buy the things we need.","cn":"我打算充分利用这次旅行来购买我们所需的物品。"}},{"pos":"PHRASE 短语","cn":"占…的便宜；欺骗；捉弄","en":"If someone takes advantage of you, they treat you unfairly for their own benefit, especially when you are trying to be kind or to help them.","ex":{"en":"She took advantage of him even after they were divorced.","cn":"甚至在他们离婚后，她还在占他的便宜。"}},{"pos":"PHRASE 短语","cn":"（尤指转变不利情况使之）对…有利","en":"If you use or turn something to your advantage, you use it in order to benefit from it, especially when it might be expected to harm or damage you.","ex":{"en":"The government have not been able to turn today's demonstration to their advantage.","cn":"政府未能把今天的游行示威转为己用。"}},{"pos":"PHRASE 短语","cn":"最有利地；最有效地；使优点突出","en":"If something is shown to good advantage or to best advantage, it is shown in a way that reveals its best features.","ex":{"en":"The walls were painted in muted tones to show the pictures to good advantage.","cn":"墙面被漆成了淡色调，以突出照片。"}}]},"examples":[{"en":"an unfair advantage (= sth that benefits you, but not your opponents)","cn":"不公平的有利因素（指有利于自己、但并不有利于对手）"},{"en":"You will be at an advantage (= have an advantage) in the interview if you have thought about the questions in advance.","cn":"如果你预先考虑过这些问题，面试就会处于优势。"}]},"advanced":{"media":{"uk":"media/uk/advanced__gb_1.mp3","us":"media/us/advanced__us_1.mp3"},"oxford":{"phon":"ədˈvɑːnst","pos":"adjective","senses":[{"en":"having the most modern and recently developed ideas, methods, etc.","cn":"先进的","ex":{"en":"Scientists are working on highly advanced technology to replace fossil fuels.","cn":"科学家们正在研究替代化石燃料的高度先进技术。"}},{"en":"at a high or difficult level","cn":"高级的；高等的","ex":{"en":"He hopes to pursue an advanced degree in economics.","cn":"他希望攻读经济学的高等学位。"}},{"en":"at a late stage of development","cn":"（发展）晚期的，后期的","ex":{"en":"the advanced stages of the disease","cn":"疾病晚期"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（制度、方法或设计）先进的","en":"An advanced system, method, or design is modern and has been developed from an earlier version of the same thing.","ex":{"en":"Without more training or advanced technical skills, they'll lose their jobs.","cn":"没有进一步的培训或高级技能的话，他们就会丢掉工作。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（国家）先进的，发达的","en":"A country that is advanced has reached a high level of industrial or technological development.","ex":{"en":"...a technologically advanced society.","cn":"科技发达的社会"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（学生）程度高的；（课程）高级的，高等的","en":"An advanced student has already learned the basic facts of a subject and is doing more difficult work. An advanced course of study is designed for such students.","ex":{"en":"The course is suitable for beginners and advanced students","cn":"本课程适合初学者及程度较高者。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"晚期的；后期的","en":"Something that is at an advanced stage or level is at a late stage of development.","ex":{"en":"'Medicare' is available to victims of advanced kidney disease","cn":"老年医疗保险也适用于肾病晚期患者。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"高龄的；年事已高的","en":"If you say that someone is of advanced years or is advanced in age, you are saying in a polite way that they are old.","ex":{"en":"The gentleman, despite his advanced years, helped Kathryn back to her seat.","cn":"这位绅士，尽管年事已高，仍然帮着凯瑟琳回到座位上。"}}]},"examples":[{"en":"( humorous ) Even at my advanced age I still know how to enjoy myself!","cn":"我虽说是黄昏暮年，也还懂得如何找乐！"},{"en":"There were only three of us on the advanced course.","cn":"只有我们三人学高级课程。"}]},"adobe":{"media":{"uk":"media/uk/adobe__gb_1.mp3","us":"media/us/adobe__us_1.mp3"},"oxford":{"phon":"əˈdəʊbi","pos":"noun","senses":[{"en":"mud that is dried in the sun, mixed with straw and used as a building material","cn":"（建筑用）黏土；黏土坯","ex":{"en":"adobe walls/houses/dwellings","cn":"土坯墙/房屋/住宅"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指热带国家建筑用的）砖坯;土坯","en":"Adobe is a mixture of mud and straw that is dried into bricks in the sun and used for building, especially in hot countries.","ex":{"en":"...a few blocks of adobe houses.","cn":"几个街区的土坯房"}}]}},"adaptability":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"methods, systems, or rules that are flexible can easily be changed if necessary","cn":""},{"en":"a system or way of doing something that is adaptable can be changed so that it is suitable for very different uses and very different situations","cn":""}]},"examples":[{"en":"The American Constitution has proved adaptable in changing political conditions.","cn":"","src":"ld"},{"en":"The catfish is adaptable to a wide range of water conditions.","cn":"","src":"ld"}],"media":{"uk":"media/uk/adaptability__gb_1.mp3","us":"media/us/adaptability__us_1.mp3"},"oxford":{"phon":"əˌdæptəˈbɪləti","pos":"noun","senses":[{"en":"the quality of being able to change or be changed in order to deal successfully with new situations","cn":"有适应能力的；能适应的","ex":{"en":"Small enterprises generally offer greater adaptability than larger firms.","cn":"小企业通常比大企业具有更强的适应性。"}}]}},"adjusting":{"oxford":{"phon":"əˈdʒʌst","pos":"verb","senses":[{"en":"to change sth slightly to make it more suitable for a new set of conditions or to make it work better","cn":"调整；调节"},{"en":"to get used to a new situation by changing the way you behave and/or think","cn":"适应；习惯"}]}},"admissions":{"oxford":{"phon":"ədˈmɪʃn","pos":"noun","senses":[{"en":"the act of accepting sb into an institution, organization, etc; the right to enter a place or to join an institution or organization （","cn":"机构、组织等的）准许加入，加入权，进入权"},{"en":"a statement in which sb admits that sth is true, especially sth wrong or bad that they have done （","cn":"尤指对过错、罪行的）承认，招认，招供"}]},"media":{"uk":"media/uk/admission__gb_1.mp3","us":"media/us/admission__us_1.mp3"}},"adverb":{"oxford":{"phon":"ˈædvɜːb","pos":"noun","senses":[{"en":"a word that adds more information about place, time, manner, cause or degree to a verb, an adjective, a phrase or another adverb","cn":"副词","ex":{"en":"In ‘speak kindly’, ‘incredibly deep’, ‘just in time’ and ‘too quickly’, ‘kindly’, ‘incredibly’, ‘just’ and ‘too’ are all adverbs.","cn":"在 speak kindly、incredibly deep、just in time 和 too quickly 四个短语中，kindly、incredibly、just 和 too 都是副词。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"副词","en":"An adverb is a word such as 'slowly', 'now', 'very', 'politically', or 'fortunately' which adds information about the action, event, or situation mentioned in a clause."}]},"media":{"uk":"media/uk/adverb__gb_1.mp3","us":"media/us/adverb__us_1.mp3"},"examples":[{"en":"In ‘speak kindly’, ‘incredibly deep’, ‘just in time’ and ‘too quickly’, ‘kindly’, ‘incredibly’, ‘just’ and ‘too’ are all adverbs.","cn":"在 speak kindly、incredibly deep、just in time 和 too quickly 四个短语中，kindly、incredibly、just 和 too 都是副词。"},{"en":"‘Very quickly indeed’ is an adverbial phrase. * very quickly indeed","cn":"是副词短语。"}]},"ad":{"media":{"uk":"media/uk/ad__gb_1.mp3","us":"media/us/ad__us_1.mp3"},"oxford":{"phon":"æd","pos":"noun","senses":[{"en":"a notice, picture or film telling people about a product, job or service","cn":"广告；启事","ex":{"en":"The TV ads were first run last year.","cn":"这则电视广告去年首次播出。"}},{"en":"used in the Christian calendar to show a particular number of years since the year when Christ was believed to have been born (from Latin ‘Anno Domini’)","cn":"公元（源自拉丁语 Anno Domini）","ex":{"en":"in (the year) AD 55","cn":"公元 55 年"},"pos":"abbreviation"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"广告","en":"An ad is an advertisement.","ex":{"en":"She replied to a lonely hearts ad.","cn":"她回应了一则征友广告。"}}]},"examples":[{"en":"in (the year) AD 55","cn":"公元 55 年"},{"en":"in 55 AD","cn":"公元 55 年"}]},"advent":{"media":{"uk":"media/uk/advent__gb_1.mp3","us":"media/us/advent__us_1.mp3"},"oxford":{"phon":"ˈædvent","pos":"noun","senses":[{"en":"the coming of an important event, person, invention, etc.","cn":"（重要事件、人物、发明等的）出现，到来","g":"[singular]","ex":{"en":"the advent of new technology","cn":"新技术的出现"}},{"en":"(in the Christian religion) the period of approximately four weeks before Christmas","cn":"（基督教）降临节，将临节（圣诞节前的四个星期左右）","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（重大事件、发明或情况的）出现，问世，到来","en":"The advent of an important event, invention, or situation is the fact of it starting or coming into existence.","ex":{"en":"...the leap forward in communication made possible by the advent of the mobile phone.","cn":"手机的问世带来了通讯业的迅猛发展"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（人物的）到达，到来","en":"The advent of a person at a place is their arrival there.","ex":{"en":"Deptford had come alive with the advent of the new priest at St Paul's.","cn":"圣保罗教堂新牧师的到来使德特福德变得生机勃勃。"}}]},"examples":[{"en":"the advent of new technology","cn":"新技术的出现"},{"en":"the advent of the computer","cn":"计算机的问世"}]},"adapt":{"media":{"uk":"media/uk/adapt__gb_1.mp3","us":"media/us/adapt__us_1.mp3"},"oxford":{"phon":"əˈdæpt","pos":"verb","senses":[{"en":"to change your behaviour in order to deal more successfully with a new situation","cn":"适应（新情况）","g":"[intransitive, transitive]","ex":{"en":"It's amazing how soon you adapt.","cn":"你这么快就适应了，真是令人惊奇。"}},{"en":"to change something in order to make it suitable for a new use or situation","cn":"使适应，使适合（新用途、新情况）","g":"[transitive]","ex":{"en":"These styles can be adapted to suit individual tastes.","cn":"这些式样可以修改，以适应个人不同爱好。"}},{"en":"to change a book or play so that it can be made into a play, film, television drama, etc.","cn":"改编；改写","g":"[transitive]","ex":{"en":"Three of her novels have been adapted for television.","cn":"她的长篇小说中有三部已经登上电视荧幕。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"适应","en":"If you adapt to a new situation or adapt yourself to it, you change your ideas or behaviour in order to deal with it successfully.","ex":{"en":"The world will be different, and we will have to be prepared to adapt to the change","cn":"世界会变得不同，我们必须做好准备以适应其变化。"}},{"pos":"VERB 动词","cn":"使适合，使适应（新用途或新情况）","en":"If you adapt something, you change it to make it suitable for a new purpose or situation.","ex":{"en":"Shelves were built to adapt the library for use as an office.","cn":"为将图书馆改作办公室而做了一些架子。"}},{"pos":"VERB 动词","cn":"改编；改写","en":"If you adapt a book or play, you change it so that it can be made into a film or a television programme.","ex":{"en":"The scriptwriter helped him to adapt his novel for the screen","cn":"编剧帮助他将其所著小说改编成电影。"}}]},"examples":[{"en":"Most of these tools have been specially adapted for use by disabled people.","cn":"这些工具多数已经过特别改装，供残疾人士使用。"},{"en":"These styles can be adapted to suit individual tastes.","cn":"这些式样可以修改，以适应个人不同爱好。"}]},"advantageous":{"media":{"uk":"media/uk/advantageous__gb_1.mp3","us":"media/us/advantageous__us_1.mp3"},"oxford":{"phon":"ˌædvənˈteɪdʒəs","pos":"adjective","senses":[{"en":"good or useful in a particular situation","cn":"有利的；有好处的","ex":{"en":"A free trade agreement would be advantageous to both countries.","cn":"自由贸易协定对两国都会有利。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有利的；有助的；有益的","en":"If something is advantageous to you, it is likely to benefit you.","ex":{"en":"Free exchange of goods was advantageous to all.","cn":"商品自由交换惠泽八方。"}}]},"examples":[{"en":"A free trade agreement would be advantageous to both countries.","cn":"自由贸易协定对两国都会有利。"},{"en":"He was now in a more advantageous position.","cn":"他现在的位置更有利。"}]},"administration":{"media":{"uk":"media/uk/administration__gb_1.mp3","us":"media/us/administration__us_1.mp3"},"oxford":{"phon":"ədˌmɪnɪˈstreɪʃn","pos":"noun","senses":[{"en":"the activities that are done in order to plan, organize and run a business, school or other institution","cn":"（企业、学校等的）管理，行政","g":"[uncountable]","lab":"informal","ex":{"en":"Administration costs are passed on to the customer.","cn":"行政费用转嫁给了消费者。"}},{"en":"the government of a country, especially the US","cn":"（尤指美国）政府","g":"[countable]","ex":{"en":"under the Trump administration","cn":"在特朗普政府领导之下"}},{"en":"the management of public affairs","cn":"公共事务管理","g":"[uncountable]","ex":{"en":"The inhabitants of the island voted to remain under French administration.","cn":"岛上的居民投票决定继续接受法国行政管理。"}},{"en":"the process or act of organizing the way that something is done","cn":"施行；执行","g":"[uncountable]","ex":{"en":"the administration of justice","cn":"司法"}},{"en":"the people who plan, organize and run a business, an institution, etc.","cn":"（企业、学校等的）管理部门，行政部门","g":"[countable]","ex":{"en":"university administrations","cn":"大学行政部门"}},{"en":"the act of giving a drug to somebody","cn":"（药物的）施用","g":"[uncountable]","lab":"formal","ex":{"en":"the administration of antibiotics","cn":"施用抗生素"}},{"en":"a situation in which the financial affairs of a business that cannot pay its debts are managed by an independent administrator","cn":"行政接管（公司破产时由独立管理人负责其运营）","g":"[uncountable]","lab":"British English, Australian English, law，，，，","ex":{"en":"If it cannot find extra funds, the company will go into administration.","cn":"如果公司筹不到额外资金，就将进入行政接管程序。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"管理;经营;行政事务","en":"Administration is the range of activities connected with organizing and supervising the way that an organization or institution functions.","ex":{"en":"Too much time is spent on administration.","cn":"在管理上花费了太多时间。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"实施;执行;监管","en":"The administration of something is the process of organizing and supervising it.","ex":{"en":"Standards in the administration of justice have degenerated","cn":"执法标准下降了。"}},{"pos":"N-SING 单数名词","cn":"（公司或机构的）管理部门，行政部门","en":"The administration of a company or institution is the group of people who organize and supervise it.","ex":{"en":"... a member of the college administration.","cn":"学院行政部门的成员"}},{"pos":"N-COUNT 可数名词","cn":"（尤指美国）政府","en":"You can refer to a country's government as the administration; used especially in the United States. →see usage note at:","ex":{"en":"O'Leary served in federal energy posts in both the Ford and Carter administrations","cn":"在福特和卡特两届政府执政期间，奥利里都在联邦能源机构中任职。"}}]},"examples":[{"en":"Successive administrations have failed to solve the country's economic problems.","cn":"一届又一届政府均未能解决这个国家的经济问题。"},{"en":"If it cannot find extra funds, the company will go into administration.","cn":"如果公司筹不到额外资金就将进入行政接管程序。"}]},"advised":{"oxford":{"phon":"ədˈvaɪz","pos":"verb","senses":[{"en":"to tell sb what you think they should do in a particular situation","cn":"劝告；忠告；建议"},{"en":"to give sb help and information on a subject that you know a lot about","cn":"出主意；提出建议；提供咨询"}]}},"advise":{"oxford":{"phon":"ədˈvaɪz","pos":"verb","senses":[{"en":"to tell somebody what you think they should do in a particular situation","cn":"劝告；忠告；建议","g":"[intransitive, transitive]","lab":"British English also","ex":{"en":"I would strongly advise against going out on your own.","cn":"我要极力奉劝你别单独外出。"}},{"en":"to give somebody help and information on a subject that you know a lot about","cn":"出主意；提出建议；提供咨询","g":"[intransitive, transitive]","ex":{"en":"We employ an expert to advise on new technology.","cn":"我们聘用了一位专家担任新技术顾问。"}},{"en":"to officially tell somebody something","cn":"通知；正式告知","g":"[transitive]","lab":"formal","ex":{"en":"Please advise us of any change of address.","cn":"如地址有变，敬请告知。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"劝告；忠告；给…出主意","en":"If you advise someone to do something, you tell them what you think they should do.","ex":{"en":"The minister advised him to leave as soon as possible","cn":"部长建议他尽快离开。"}},{"pos":"VERB 动词","cn":"（专家）建议，向…提供意见","en":"If an expert advises people on a particular subject, he or she gives them help and information on that subject.","ex":{"en":"...an officer who advises undergraduates on money matters","cn":"为本科生们提供理财建议的高级职员"}},{"pos":"VERB 动词","cn":"通知，告知（某人事实或情况）","en":"If you advise someone of a fact or situation, you tell them the fact or explain what the situation is.","ex":{"en":"...the decision requiring police to advise suspects of their rights","cn":"要求警方告知疑犯他们所享权利的决定"}},{"pos":"V-PASSIVE 被动动词","cn":"（官方文件）告知","en":"If an official document states that you are advised to do something, it is telling you the correct or appropriate thing to do.","ex":{"en":"Candidates in India are advised to submit their applications through the overseas student office in London","cn":"印度的申请人被告知通过驻伦敦的海外学生办公室递交申请表。"}}]},"media":{"uk":"media/uk/advise__gb_1.mp3","us":"media/us/advise__us_1.mp3"},"examples":[{"en":"I'd advise buying your tickets well in advance if you want to travel in August.","cn":"要是想在八月份去旅行，我建议及早购票。"},{"en":"Her mother was away and couldn't advise her.","cn":"她的母亲不在身边，无法向她提出劝告。"}]},"advertise":{"oxford":{"phon":"ˈædvətaɪz","pos":"verb","senses":[{"en":"to tell the public about a product or a service in order to encourage people to buy or to use it","cn":"做广告；登广告","g":"[intransitive, transitive]","ex":{"en":"If you want to attract customers you need to advertise.","cn":"要想吸引顾客，就得做广告。"}},{"en":"to let people know that something is going to happen, or that a job is available by giving details about it in a newspaper, on a notice in a public place, on the internet, etc.","cn":"（在报纸、公共场所公告牌、互联网等上）公布，征聘","g":"[intransitive, transitive]","ex":{"en":"Sellers pay upfront to advertise.","cn":"卖家预先支付广告费。"}},{"en":"to show or tell something about yourself to other people","cn":"展现，宣传（自己的事）","g":"[transitive]","ex":{"en":"I wouldn't advertise the fact that you don't have a work permit.","cn":"我不会向外声张你没有工作许可证这件事。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"为…做广告;宣传","en":"If you advertise something such as a product, an event, or a job, you tell people about it in newspapers, on television, or on posters in order to encourage them to buy the product, go to the event, or apply for the job.","ex":{"en":"The players can advertise baked beans, but not rugby boots","cn":"球员可以给烤菜豆做广告，但不能代言橄榄球靴。"}},{"pos":"VERB 动词","cn":"（在报纸、电视、公告栏上）登广告招募，登广告征求","en":"If you advertise for someone to do something for you, for example to work for you or share your accommodation, you announce it in a newspaper, on television, or on a notice board.","ex":{"en":"We advertised for staff in a local newspaper","cn":"我们在一家地方报纸上刊登了招聘广告。"}},{"pos":"VERB 动词","cn":"（通过外表或行为）显示（某种特质）；使变得显眼","en":"If someone or something advertises a particular quality, they show it in their appearance or behaviour.","ex":{"en":"His hard sinewy body advertised his ruthlessness of purpose.","cn":"他健硕的身体使他显得意志尤为坚强。"}},{"pos":"VERB 动词","cn":"宣扬；张扬；引起对…的注意","en":"If you do not advertise the fact that something is the case, you try not to let other people know about it.","ex":{"en":"There is no need to advertise the fact that you are a single woman","cn":"没有必要张扬你是一个单身女性。"}}]},"media":{"uk":"media/uk/advertise__gb_1.mp3","us":"media/us/advertise__us_1.mp3"},"examples":[{"en":"If you want to attract more customers, try advertising in the local paper.","cn":"如果你要吸引更多顾客，就试试在当地报纸登广告。"},{"en":"I wouldn't advertise the fact that you don't have a work permit.","cn":"我不会向外声张你没有工作许可证这件事。"}]},"adopt":{"media":{"uk":"media/uk/adopt__gb_1.mp3","us":"media/us/adopt__us_1.mp3"},"oxford":{"phon":"əˈdɒpt","pos":"verb","senses":[{"en":"to take somebody else’s child into your family and become its legal parent(s)","cn":"收养；领养","g":"[intransitive, transitive]","lab":"especially US English","sc":"child","ex":{"en":"a campaign to encourage childless couples to adopt","cn":"鼓励无子女夫妇领养孩子的运动"}},{"en":"to start to use a particular method or to show a particular attitude towards somebody/something","cn":"采用（某方法）；采取（某态度）","g":"[transitive]","sc":"method","ex":{"en":"All three teams adopted different approaches to the problem.","cn":"三个队处理这个问题的方法各不相同。"}},{"en":"to formally accept a suggestion or policy by voting","cn":"正式通过，表决采纳（建议、政策等）","g":"[transitive]","sc":"suggestion","ex":{"en":"The government adopted a resolution on disarmament.","cn":"政府通过了一项关于裁军的决议。"}},{"en":"to choose a new name, a country, a custom, etc. and begin to use it as your own","cn":"选用（名字等）；移居（某国）；承袭（风俗）","g":"[transitive]","sc":"new name/country","ex":{"en":"to adopt a name/title/language","cn":"取名；袭用头衔；采用某语言"}},{"en":"to use a particular manner, way of speaking, expression, etc.","cn":"采用（某种举止、说话方式等）","g":"[transitive]","lab":"formal","sc":"way of behaving","ex":{"en":"He adopted an air of indifference.","cn":"他摆出一副满不在乎的样子。"}},{"en":"to choose somebody as a candidate in an election; to choose somebody as your representative","cn":"选定，选举（某人为候选人或代表）","g":"[transitive]","lab":"British English, politics，，","sc":"candidate","ex":{"en":"She was adopted as parliamentary candidate for Wood Green.","cn":"她被推举为伍德格林选区的议员候选人。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"采取；采纳；采用","en":"If you adopt a new attitude, plan, or way of behaving, you begin to have it.","ex":{"en":"Parliament adopted a resolution calling for the complete withdrawal of troops","cn":"议会采纳了要求全部撤军的决议。"}},{"pos":"VERB 动词","cn":"收养;领养","en":"If you adopt someone else's child, you take it into your own family and make it legally your son or daughter.","ex":{"en":"There are hundreds of people desperate to adopt a child","cn":"有数以百计的人渴望领养孩子。"}},{"pos":"VERB 动词","cn":"采用，保持（姿势）","en":"If you adopt a physical position, you move yourself into it.","ex":{"en":"I tried to adopt a curled-up position to avoid damaging my limbs.","cn":"我努力保持蜷曲的姿势以免四肢受伤。"}},{"pos":"VERB 动词","cn":"移居（某国）;选择（某国）定居","en":"If you adopt a country, you choose it as a place to live.","ex":{"en":"Podulski had joined the U.S. Navy as an aviator, adopting a new country and a new profession.","cn":"波度尔斯基加入美国海军当上了飞行员，不仅改了国籍还换了行当。"}},{"pos":"VERB 动词","cn":"采用（语气、口音等）","en":"If you adopt an accent or a particular tone of voice, you speak differently from normal, especially to create an effect in a particular situation.","ex":{"en":"He has adopted the accent of a Second World War newscaster","cn":"他承袭了二战时期播音员的口音。"}}]},"examples":[{"en":"Early Christians in Europe adopted many of the practices of the older, pagan religions.","cn":"欧洲早期的基督教徒承袭了更古老的一些异教的许多习俗。"},{"en":"The council is expected to adopt the new policy at its next meeting.","cn":"委员会有望在下次会议上正式通过这项新政策。"}]},"advocate":{"media":{"uk":"media/uk/advocate__gb_1.mp3","us":"media/us/advocate__us_1.mp3"},"oxford":{"phon":"ˈædvəkət","pos":"noun","senses":[{"en":"a person who supports or speaks in favour of somebody or of a public plan or action","cn":"拥护者；支持者；提倡者","lab":"formal","ex":{"en":"an advocate for hospital workers","cn":"医院工作人员的支持者"}},{"en":"a person who defends somebody in court","cn":"辩护律师；出庭辩护人","lab":"law","ex":{"en":"Solicitors often appear as advocates in the lower courts.","cn":"律师经常在下级法院作为辩护人出庭。"}},{"en":"(in Scotland and South Africa) a lawyer who has the right to argue cases in higher courts","cn":"（苏格兰）出庭律师，辩护律师，大律师","lab":"law"},{"en":"to support something publicly","cn":"拥护；支持；提倡","lab":"British English also","ex":{"en":"The group does not advocate the use of violence.","cn":"该团体不支持使用暴力。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"拥护；提倡；主张","en":"If you advocate a particular action or plan, you recommend it publicly.","ex":{"en":"Mr Williams is a conservative who advocates fewer government controls on business.","cn":"威廉斯先生是个保守派，主张政府应减少对商业的控制。"}},{"pos":"N-COUNT 可数名词","cn":"拥护者；提倡者","en":"An advocate of a particular action or plan is someone who recommends it publicly.","ex":{"en":"He was a strong advocate of free market policies and a multi-party system.","cn":"他是自由市场政策和多党派制度的坚决拥护者。"}},{"pos":"N-COUNT 可数名词","cn":"辩护律师","en":"An advocate is a lawyer who speaks in favour of someone or defends them in a court of law. →see usage note at:"},{"pos":"N-COUNT 可数名词","cn":"（为某一类人）谋利益者","en":"An advocate for a particular group is a person who works for the interests of that group.","ex":{"en":"...advocates for the homeless","cn":"为无家可归的人谋利益者"}}]},"examples":[{"en":"The report advocated that all buildings be fitted with smoke detectors.","cn":"报告主张所有的建筑物都应安装烟火探测器。"},{"en":"( BrE also ) The report advocated that all buildings should be fitted with smoke detectors.","cn":"报告主张所有的建筑物都应安装烟火探测器。"}]},"adhere":{"oxford":{"phon":"ədˈhɪə(r)","pos":"verb","senses":[{"en":"to stick to something","cn":"黏附；附着","ex":{"en":"Once in the bloodstream, the bacteria adhere to the surface of the red cells.","cn":"细菌一进入血液里，就附着在红细胞表面上。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"遵守，遵循（规定或协议）","en":"If you adhere to a rule or agreement, you act in the way that it says you should.","ex":{"en":"All members of the association adhere to a strict code of practice","cn":"协会的所有成员都遵守一套严格的行为规范。"}},{"pos":"VERB 动词","cn":"支持，拥护，持有（观点或信仰）","en":"If you adhere to an opinion or belief, you support or hold it.","ex":{"en":"He urged them to adhere to the values of Islam which defend the dignity of man.","cn":"他鼓励他们坚守伊斯兰教维护人类尊严的价值观。"}},{"pos":"VERB 动词","cn":"黏附；附着","en":"If something adheres to something else, it sticks firmly to it.","ex":{"en":"Small particles adhere to the seed","cn":"小颗粒牢牢附着在种子上。"}}]},"media":{"uk":"media/uk/adhere__gb_1.mp3","us":"media/us/adhere__us_1.mp3"},"examples":[{"en":"Once in the bloodstream, the bacteria adhere to the surface of the red cells.","cn":"细菌一进入血液里，就附着在红细胞表面上。"},{"en":"She adheres to teaching methods she learned over 30 years ago.","cn":"她依循她 30 多年前所学的教学法教学。"}]},"adept":{"media":{"uk":"media/uk/adept__gb_1.mp3","us":"media/us/adept__us_1.mp3"},"oxford":{"phon":"əˈdept","pos":"adjective","senses":[{"en":"good at doing something that is quite difficult","cn":"内行的；熟练的；擅长的","ex":{"en":"He became adept at getting even the shyest students to talk.","cn":"他变得善于让最害羞的学生开口说话。"}},{"en":"a person who is good at doing something that is quite difficult","cn":"内行的；熟练的；擅长的","ex":{"en":"He was an adept at concealing the truth.","cn":"他善于隐瞒真相。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"熟练的；擅长的；内行的","en":"Someone who is adept at something can do it skilfully.","ex":{"en":"He's usually very adept at keeping his private life out of the media","cn":"他通常很善于使自己的私生活避开媒体的关注。"}}]},"examples":[{"en":"Melissa quickly became adept at predicting his moods.","cn":"很快梅莉莎就学会了预测他的情绪。"},{"en":"Silas proved adept in the art of avoiding potholes in the road.","cn":"赛拉斯看来很善于避开路上的坑坑洼洼。"}]},"adults":{"oxford":{"phon":"ˈædʌlt","pos":"noun","senses":[{"en":"a fully grown person who is legally responsible for their actions （","cn":"法律上指能为自己的行为负责的）成年人"},{"en":"a fully grown animal","cn":"成年动物"}]}},"addition":{"media":{"uk":"media/uk/addition__gb_1.mp3","us":"media/us/addition__us_1.mp3"},"oxford":{"phon":"əˈdɪʃn","pos":"noun","senses":[{"en":"a thing that is added to something else","cn":"增加物；添加物","g":"[countable]","ex":{"en":"All of these technologies are fairly recent additions.","cn":"所有这些技术都是最近添加的。"}},{"en":"the act of adding something to something else","cn":"增加；添加","g":"[uncountable]","ex":{"en":"Add salt, tasting with every addition.","cn":"添加盐，每次添加时品尝。"}},{"en":"a new part that is added to a building","cn":"（建筑物的）扩建部分，增建部分","g":"[countable]","lab":"North American English","ex":{"en":"architects who specialize in home additions","cn":"专门从事住宅扩建的建筑师"}},{"en":"the process of adding two or more numbers together to find their total","cn":"加；加法","g":"[uncountable]","ex":{"en":"children learning addition and subtraction","cn":"学习加减的儿童"}}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"另外;加之;除…之外","en":"You use in addition when you want to mention another item connected with the subject you are discussing.","ex":{"en":"Part-time English classes are offered. In addition, students can take classes in word-processing and computing","cn":"开设了非全日制的英语班。另外，学生可以修读文字处理和计算机课程。"}},{"pos":"N-COUNT 可数名词","cn":"增加物；添加物","en":"An addition to something is a thing which is added to it.","ex":{"en":"This is a fine book; a worthy addition to the Cambridge Encyclopedia series","cn":"这是一本好书，对剑桥百科全书系列是一个很好的补充。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"增加；添加","en":"The addition of something is the fact that it is added to something else.","ex":{"en":"It was completely refurbished in 1987, with the addition of a picnic site.","cn":"它在1987年经过了彻底翻修，加盖了一个野餐点。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"加；算总数","en":"Addition is the process of calculating the total of two or more numbers.","ex":{"en":"...simple addition and subtraction problems.","cn":"简单的加减题"}}]},"examples":[{"en":"Pasta's basic ingredients are flour and water, sometimes with the addition of eggs or oil.","cn":"意大利面制品的主要成分是面粉和水，有时加鸡蛋和食用油。"},{"en":"In addition to these arrangements, extra ambulances will be on duty until midnight.","cn":"除了这些安排以外，另增救护车值班至午夜。"}]},"address":{"media":{"uk":"media/uk/address__gb_1.mp3","us":"media/us/address__us_3.mp3"},"oxford":{"phon":"əˈdres","pos":"noun","senses":[{"en":"details of where somebody lives or works and where letters, etc. can be sent","cn":"住址；地址；通信处","g":"[countable]","lab":"especially North American English","ex":{"en":"What's your name and address?","cn":"你的姓名、住址？"}},{"en":"a series of words and symbols that tells you where you can find something using a computer or phone, for example on the internet","cn":"（互联网等的）地址","g":"[countable]","lab":"computing","ex":{"en":"What's your email address?","cn":"你的电邮地址是什么？"}},{"en":"a formal speech that is made in front of an audience","cn":"演说；演讲","g":"[countable]","lab":"especially North American English","ex":{"en":"tonight’s televised presidential address","cn":"今晚总统的电视演讲"}},{"en":"the correct title, etc. to use when you talk to somebody","cn":"称呼","g":"[uncountable]"},{"en":"to think about a problem or a situation and decide how you are going to deal with it","cn":"设法解决；处理；对付","lab":"formal","ex":{"en":"Your essay does not address the real issues.","cn":"你的论文没有论证实质问题。"},"pos":"verb"},{"en":"to write on an envelope, etc. the name and address of the person, company, etc. that you are sending it to by mail","cn":"写（收信人）姓名地址；致函","g":"[often passive]","ex":{"en":"The letter was correctly addressed, but delivered to the wrong house.","cn":"信上的姓名地址写得都对，但被错投到另一家去了。"},"pos":"verb"},{"en":"to make a formal speech to a group of people","cn":"演说；演讲","ex":{"en":"to address a meeting/conference","cn":"在会议／大会上发表演讲"},"pos":"verb"},{"en":"to say something directly to somebody","cn":"向…说话","lab":"formal","ex":{"en":"I was surprised when he addressed me in English.","cn":"他用英语跟我说话，我很诧异。"},"pos":"verb"},{"en":"to use a particular name or title for somebody when you speak or write to them","cn":"称呼（某人）；冠以（某种称呼）","ex":{"en":"There are different ways in which to address a member of the royal family.","cn":"称呼王室成员有不同的方式。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"住址；地址","en":"Your address is the number of the house, flat, or apartment and the name of the street and the town where you live or work.","ex":{"en":"The address is 2025 M Street, Northwest, Washington, DC, 20036","cn":"地址为华盛顿特区，西北区，M大街2025号，邮政编码20036。"}},{"pos":"VERB 动词","cn":"寄往;寄给","en":"If a letter, envelope, or parcel is addressed to you, your name and address have been written on it.","ex":{"en":"Applications should be addressed to: The business affairs editor.","cn":"申请表应寄给;商务编辑。"}},{"pos":"N-COUNT 可数名词","cn":"网址","en":"The address of a website is its location on the Internet, for example http://www.cobuild.collins.co.uk.","ex":{"en":"Internet addresses are also known as URLs.","cn":"网址也被称作URL。"}},{"pos":"N-COUNT 可数名词","cn":"（电子表格中某个单元格的）位置","en":"The address of a cell on a computer spreadsheet refers to the particular row and column number where it is located, for example 'C2' or 'N63'."},{"pos":"VERB 动词","cn":"向…作正式讲话;对…发表演说","en":"If you address a group of people, you give a speech to them.","ex":{"en":"He is due to address a conference on human rights next week.","cn":"他下星期将在一个大会上发表关于人权的演说。"}},{"pos":"VERB 动词","cn":"向…说话","en":"If you address someone or address a remark to them, you say something to them.","ex":{"en":"The two foreign ministers did not address each other directly when they last met","cn":"这两位外交部长在上次会面时并没有直接的言语交流。"}},{"pos":"VERB 动词","cn":"称呼（某人）；给…冠以（某种称呼）","en":"If you address someone by a name or a title such as 'sir', you call them that name or title when you talk or write to them.","ex":{"en":"I heard him address her as darling","cn":"我听见他称她为“亲爱的”。"}},{"pos":"VERB 动词","cn":"对付；处理；设法了解并解决","en":"If you address a problem or task or if you address yourself to it, you try to understand it or deal with it.","ex":{"en":"Mr King sought to address those fears when he spoke at the meeting","cn":"金先生在会上讲话时试图消除那些恐惧。"}}]},"examples":[{"en":"The letter was correctly addressed, but delivered to the wrong house.","cn":"信上的姓名地址写得都对，但被错投到另一家去了。"},{"en":"Police found him at an address (= a house or flat/apartment) in West London.","cn":"警方在伦敦西区一处住所里找到了他。"}]},"adjusted":{"oxford":{"phon":"əˈdʒʌst","pos":"verb","senses":[{"en":"to change sth slightly to make it more suitable for a new set of conditions or to make it work better","cn":"调整；调节"},{"en":"to get used to a new situation by changing the way you behave and/or think","cn":"适应；习惯"}]}},"addict":{"media":{"uk":"media/uk/addict__gb_1.mp3","us":"media/us/addict__us_1.mp3"},"oxford":{"phon":"ˈædɪkt","pos":"noun","senses":[{"en":"a person who is unable to stop using or doing something as a habit, especially something harmful","cn":"成瘾者；瘾君子","ex":{"en":"a heroin/drug addict","cn":"吸食海洛因／毒品成瘾的人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"吸毒成瘾者；瘾君子","en":"An addict is someone who takes harmful drugs and cannot stop taking them.","ex":{"en":"He's only 24 years old and a drug addict.","cn":"他只有24岁，却是个瘾君子。"}},{"pos":"N-COUNT 可数名词","cn":"对…入迷的人;…迷","en":"If you say that someone is an addict, you mean that they like a particular activity very much and spend as much time doing it as they can.","ex":{"en":"She is a TV addict and watches as much as she can.","cn":"她是个电视迷，看起电视来没完没了。"}}]},"examples":[{"en":"a heroin/drug/nicotine addict","cn":"吸食海洛因/毒品/尼古丁成瘾的人"},{"en":"a video game addict","cn":"游戏机迷"}]},"adult":{"oxford":{"phon":"ˈædʌlt","pos":"noun","senses":[{"en":"a fully grown person who is legally responsible for their actions","cn":"（法律上指能为自己的行为负责的）成年人","ex":{"en":"Children must be accompanied by an adult.","cn":"儿童必须要有大人陪同。"}},{"en":"a fully grown animal","cn":"成年动物","ex":{"en":"The fish return to the river as adults in order to breed.","cn":"这种鱼长成以后回到河中产卵。"}},{"en":"fully grown or developed","cn":"成年的；发育成熟的","ex":{"en":"preparing young people for adult life","cn":"指导年轻人准备过成人生活"},"pos":"adjective"},{"en":"behaving in an intelligent and responsible way; typical of what is expected of an adult","cn":"（智力、思想、行为）成熟的，成人的","ex":{"en":"When my parents split up, it was all very adult and open.","cn":"我父母离异时，事情处理得很成熟、很开放。"},"pos":"adjective"},{"en":"intended for adults only because it is about sex or shows people with no clothes on","cn":"仅限成人的（因有色情内容）","g":"[only before noun]","ex":{"en":"an adult movie","cn":"仅供成人观看的电影"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（法律意义上的）成年人","en":"An adult is a mature, fully developed person. An adult has reached the age when they are legally responsible for their actions.","ex":{"en":"Becoming a father signified that he was now an adult","cn":"当了父亲意味着他已是个成年人了。"}},{"pos":"N-COUNT 可数名词","cn":"成年动物","en":"An adult is a fully developed animal.","ex":{"en":"...a pair of adult birds.","cn":"一对成年鸟"}},{"pos":"ADJ 形容词","cn":"成年的；属于成人的","en":"Adult means relating to the time when you are an adult, or typical of adult people.","ex":{"en":"I've lived most of my adult life in London.","cn":"我成年之后的大部分时间都是在伦敦度过的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"成熟的；老成的","en":"If you say that someone is adult about something, you think that they act in a mature, intelligent way, especially when faced with a difficult situation.","ex":{"en":"We were very adult about it. We discussed it rationally over a drink.","cn":"在这件事上我们表现得很成熟。我们一边喝酒一边心平气和地谈了谈。"}},{"pos":"ADJ 形容词","cn":"（涉及性内容的电影或书籍）仅限于成人的","en":"You can describe things such as films or books as adult when they deal with sex in a very clear and open way.","ex":{"en":"...an adult movie.","cn":"成人电影"}}]},"media":{"uk":"media/uk/adult__gb_1.mp3","us":"media/us/adult__us_1.mp3"},"examples":[{"en":"Why can't you two act like civilized adults?","cn":"你们俩为什么就不能像有教养的成年人那样行事呢？"},{"en":"When my parents split up, it was all very adult and open.","cn":"我父母离异时，事情处理得很成熟、很开放。"}]},"admission":{"media":{"uk":"media/uk/admission__gb_1.mp3","us":"media/us/admission__us_1.mp3"},"oxford":{"phon":"ədˈmɪʃn","pos":"noun","senses":[{"en":"the act of accepting somebody into an institution, organization, etc.; the right to enter a place or to join an institution or organization","cn":"（机构、组织等的）准许加入，加入权，进入权","g":"[uncountable, countable]","ex":{"en":"Hospital admission is not necessary in most cases.","cn":"大多数情况下，病人无须住院。"}},{"en":"a statement in which somebody admits that something is true, especially something wrong or bad that they have done","cn":"（尤指对过错、罪行的）承认，招认，招供","g":"[countable]","ex":{"en":"He is a thief by his own admission (= he has admitted it).","cn":"他自己供认是小偷。"}},{"en":"the amount of money that you pay to go into a building or to an event","cn":"入场费；门票费","g":"[uncountable]","ex":{"en":"admission charges/prices","cn":"入场费"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"准许进入；准许加入；进入；加入","en":"Admission is permission given to a person to enter a place, or permission given to a country to enter an organization. Admission is also the act of entering a place.","ex":{"en":"Students apply for admission to a particular college","cn":"学生们申请上某所大学。"}},{"pos":"N-PLURAL 复数名词","cn":"获准入学者","en":"Admissions to a place such as a school or university are the people who are allowed to enter or join it.","ex":{"en":"Each school sets its own admissions policy.","cn":"每所学校制定各自的录取政策。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"入场费；门票费","en":"Admission at a park, museum, or other place is the amount of money that you pay to enter it.","ex":{"en":"Gates open at 10.30am and admission is free.","cn":"早上10:30开门，免费入场。"}},{"pos":"N-VAR 可变名词","cn":"（对过错等的）承认，供认","en":"An admission is a statement that something bad, unpleasant, or embarrassing is true.","ex":{"en":"By his own admission, he is not playing well","cn":"他自己承认表现欠佳。"}}]},"examples":[{"en":"They tried to get into the club but were refused admission.","cn":"他们试图进入俱乐部，但遭到了拒绝。"},{"en":"Last admissions to the park are at 4 p.m.","cn":"公园最后的入园时间是下午 4 点。"}]},"adjust":{"oxford":{"phon":"əˈdʒʌst","pos":"verb","senses":[{"en":"to change something slightly to make it more suitable for a new set of conditions or to make it work better","cn":"调整；调节","g":"[transitive]","ex":{"en":"Watch out for sharp bends and adjust your speed accordingly.","cn":"当心急转弯并相应调整车速。"}},{"en":"to get used to a new situation by changing the way you behave and/or think","cn":"适应；习惯","g":"[intransitive, transitive]","ex":{"en":"They'll be fine—they just need time to adjust.","cn":"他们会好起来的，只是需要时间来适应。"}},{"en":"to move something slightly so that it looks neater or feels more comfortable","cn":"整理","g":"[transitive]","ex":{"en":"He smoothed his hair and adjusted his tie.","cn":"他捋平头发，整了整领带。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"改变（行为或观点）以适应;调节;习惯","en":"When you adjust to a new situation, you get used to it by changing your behaviour or your ideas.","ex":{"en":"We have been preparing our fighters to adjust themselves to civil society","cn":"我们一直在培训我们的战士，以使他们适应普通的社会生活。"}},{"pos":"VERB 动词","cn":"调整；调节","en":"If you adjust something, you change it so that it is more effective or appropriate.","ex":{"en":"To attract investors, Panama has adjusted its tax and labour laws.","cn":"为吸引投资者，巴拿马调整了税法和劳动法。"}},{"pos":"VERB 动词","cn":"整理（衣服）；校正，校准（机器）","en":"If you adjust something such as your clothing or a machine, you correct or alter its position or setting.","ex":{"en":"She adjusted her head scarf fussily","cn":"她小题大做地整了整头巾。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）适应（光线变化）","en":"If you adjust your vision or if your vision adjusts, the muscles of your eye or the pupils alter to cope with changes in light or distance.","ex":{"en":"He stopped to try to adjust his vision to the faint starlight","cn":"他停下脚步试着让眼睛适应微弱的星光。"}}]},"media":{"uk":"media/uk/adjust__gb_1.mp3","us":"media/us/adjust__us_1.mp3"},"examples":[{"en":"They'll be fine — they just need time to adjust.","cn":"他们会好起来的，只是需要时间来适应。"},{"en":"Adjust your language to the age of your audience.","cn":"要根据听众的年龄使用相应的语言。"}]},"adequate":{"media":{"uk":"media/uk/adequate__gb_1.mp3","us":"media/us/adequate__us_1.mp3"},"oxford":{"phon":"ˈædɪkwət","pos":"adjective","senses":[{"en":"enough in quantity, or good enough in quality, for a particular purpose or need","cn":"足够的；合格的；合乎需要的","ex":{"en":"They'll need an adequate supply of hot water.","cn":"他们需要有充足的热水。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"足够的；合格的；可用的","en":"If something is adequate, there is enough of it or it is good enough to be used or accepted.","ex":{"en":"One in four people worldwide are without adequate homes","cn":"全世界有1/4的人没有个像样的家。"}}]},"examples":[{"en":"He didn't give an adequate answer to the question.","cn":"他没有对这个问题作出满意的答复。"},{"en":"The space available is not adequate for our needs.","cn":"现有的空间不能满足我们的需要。"}]},"advocacy":{"media":{"uk":"media/uk/advocacy__gb_1.mp3","us":"media/us/advocacy__us_1.mp3"},"oxford":{"phon":"ˈædvəkəsi","pos":"noun","senses":[{"en":"public support that somebody gives to an idea, a course of action or a belief","cn":"（对某思想、行动方针、信念的）拥护，支持，提倡","lab":"formal","ex":{"en":"He won the Peace Prize for his advocacy of non-violent protest.","cn":"他因倡导非暴力抗议而获得和平奖。"}},{"en":"support, advice and help given to people, often with special needs or aims, who are unable to speak for themselves","cn":"（给予有特殊需求者的）支持，意见，帮助","ex":{"en":"We are a charity that provides information, advocacy and advice to people with mental health issues.","cn":"我们是一家慈善机构，为有心理健康问题的人们提供信息、宣传和建议。"}},{"en":"the work of lawyers who speak about cases in court","cn":"（律师）出庭辩护；律师的工作","lab":"specialist"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"拥护；提倡；主张","en":"Someone's advocacy of a particular action or plan is their act of recommending it publicly.","ex":{"en":"I support your advocacy of free trade.","cn":"我支持你自由贸易的主张。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"辩护；辩护术","en":"Advocacy is the way in which lawyers deal with cases in court.","ex":{"en":"Sir Peter would also like to see the current adversarial system of advocacy examined by the royal commission.","cn":"彼得爵士也乐于见到王室委员会审查当前对抗式的辩护制度。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（试图影响政府或其他权力机构决策的）游说（团体或组织）","en":"An advocacy group or organization is one that tries to influence the decisions of a government or other authority.","ex":{"en":"Consumer advocacy groups are not so enthusiastic about removing restrictions on the telephone companies.","cn":"保护消费者团体并不热衷于取消对电话公司的限制。"}}]}},"adapting":{"oxford":{"phon":"əˈdæpt","pos":"verb","senses":[{"en":"to change sth in order to make it suitable for a new use or situation","cn":"使适应，使适合（新用途、新情况）"},{"en":"to change your behaviour in order to deal more successfully with a new situation","cn":"适应（新情况）"}]}},"advocates":{"oxford":{"phon":"ˈædvəkeɪt","pos":"verb","senses":[{"en":"( formal ) to support sth publicly","cn":"拥护；支持；提倡"},{"en":"a person who supports or speaks in favour of sb or of a public plan or action","cn":"拥护者；支持者；提倡者"}]}},"added":{"oxford":{"phon":"æd","pos":"verb","senses":[{"en":"to put sth together with sth else so as to increase the size, number, amount, etc.","cn":"增加；加添"},{"en":"to put numbers or amounts together to get a total","cn":"加"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"附加的；额外的","en":"You use added to say that something has more of a particular thing or quality.","ex":{"en":"For added protection choose a lipstick with a sun screen.","cn":"选择防晒护唇膏来增强保护。"}}]},"media":{"uk":"media/ldoce/hwd/bre/4/added0205.mp3","us":"media/ldoce/hwd/ame/0/added.mp3"}},"addressing":{"oxford":{"phon":"əˈdres","pos":"noun","senses":[{"en":"details of where sb lives or works and where letters, etc. can be sent","cn":"住址；地址；通信处"},{"en":"( computing","cn":"计 ) a series of words and symbols that tells you where you can find sth using a computer, for example on the Internet （互"}]}},"advances":{"oxford":{"phon":"ədˈvɑːns","pos":"noun","senses":[{"en":"the forward movement of a group of people, especially armed forces （","cn":"尤指武装部队的）前进，行进"},{"en":"progress or a development in a particular activity or area of understanding","cn":"进步；进展"}]}},"administrators":{"oxford":{"phon":"ədˈmɪnɪstreɪtə(r)","pos":"noun","senses":[{"en":"a person whose job is to manage and organize the public or business affairs of a company or an institution （","cn":"公司、机构的）管理人员，行政人员"}]}},"advantages":{"oxford":{"phon":"ədˈvɑːntɪdʒ","pos":"noun","senses":[{"en":"a thing that helps you to be better or more successful than other people","cn":"有利条件；有利因素；优势"},{"en":"a quality of sth that makes it better or more useful","cn":"优点"}]}},"adopters":{"oxford":{"phon":"əˈdɒptə(r)","pos":"noun","senses":[{"en":"a person who adopts a child","cn":"收养者"},{"en":"a person who starts using a new technology （","cn":"新技术）采用者"}]}},"admired":{"oxford":{"phon":"ədˈmaɪə(r)","pos":"verb","senses":[{"en":"to respect sb for what they are or for what they have done","cn":"钦佩；赞赏；仰慕"},{"en":"to look at sth and think that it is attractive and/or impressive","cn":"欣赏"}]}},"adopting":{"oxford":{"phon":"əˈdɒpt","pos":"verb","senses":[{"en":"to take sb else's child into your family and become its legal parent(s)","cn":"收养；领养"},{"en":"to start to use a particular method or to show a particular attitude towards sb/sth","cn":"采用（某方法）；采取（某态度）"}]}},"adds":{"oxford":{"phon":"æd","pos":"verb","senses":[{"en":"to put sth together with sth else so as to increase the size, number, amount, etc.","cn":"增加；加添"},{"en":"to put numbers or amounts together to get a total","cn":"加"}]}},"adding":{"oxford":{"phon":"æd","pos":"verb","senses":[{"en":"to put sth together with sth else so as to increase the size, number, amount, etc.","cn":"增加；加添"},{"en":"to put numbers or amounts together to get a total","cn":"加"}]}},"adventures":{"oxford":{"phon":"ədˈventʃə(r)","pos":"noun","senses":[{"en":"an unusual, exciting or dangerous experience, journey or series of events","cn":"冒险；冒险经历；奇遇"},{"en":"excitement and the willingness to take risks, try new ideas, etc.","cn":"冒险的刺激；大胆开拓"}]}},"adolescents":{"oxford":{"phon":"ˌædəˈlesnt","pos":"noun","senses":[{"en":"a young person who is developing from a child into an adult","cn":"青少年"}]}},"adapted":{"oxford":{"phon":"əˈdæpt","pos":"verb","senses":[{"en":"to change sth in order to make it suitable for a new use or situation","cn":"使适应，使适合（新用途、新情况）"},{"en":"to change your behaviour in order to deal more successfully with a new situation","cn":"适应（新情况）"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"适用于…的;适合…的","en":"If something is adapted to a particular situation or purpose, it is especially suitable for it.","ex":{"en":"The camel's feet, well adapted for dry sand, are useless on mud.","cn":"骆驼的蹄子虽然非常适合于在干沙上行走，碰到泥泞时却无计可施。"}}]},"media":{"uk":"media/ldoce/hwd/bre/f/adapt0205.mp3","us":"media/ldoce/hwd/ame/e/adapt.mp3"},"examples":[{"en":"The children are finding it hard to adapt to the new school.","cn":""},{"en":"flowers which are well adapted to harsh winters","cn":""}]},"admirer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钦佩者；欣赏者","en":"If you are an admirer of someone, you like and respect them or their work very much.","ex":{"en":"He was an admirer of her grandfather's paintings.","cn":"他非常欣赏她祖父的画作。"}},{"pos":"N-COUNT 可数名词","cn":"（女人的）追求者,爱慕者","en":"A woman's admirers are the men who are attracted to her.","ex":{"en":"Johnny was the most persistent and most harmless of her admirers.","cn":"约翰尼是追她的人中最痴心、最没有心机的一个。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to have a very good opinion of someone, either because they have achieved something special or because they have skills or qualities that you would like to have","cn":""},{"en":"to have a good opinion of someone, even if you do not agree with them or want to be like them, because they have high standards and good personal qualities","cn":""},{"en":"to respect and admire someone who is older than you or who has authority over you","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An admirer is a fan, supporter, or lover. If you're an admirer of Jane Austen, you are enthusiastic about her novels and appreciate her writing."}]},"collocations":{"phrases":["ADJ. ardent, devoted, fervent, great, keen | secret Perhaps the flowers were sent by a secret admirer!","QUANT. band, circle, host She was always surrounded by a circle of admirers.","VERB + ADMIRER have | gain, win She soon gained admirers in England and France.","PHRASES friends and admirers The funeral was attended by the singer's friends and admirers."]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41admirer.mp3","us":"media/ldoce/hwd/ame/a/admirer.mp3"},"examples":[{"en":"He is a great admirer of Picasso's early paintings.","cn":"他十分赞赏毕加索的早期画作。"},{"en":"She never married but had many admirers.","cn":"她从未结婚，不过追求者不少。"}],"oxford":{"phon":"ədˈmaɪərə(r)","pos":"noun","senses":[{"en":"a person who admires somebody/something, especially a well-known person or thing","cn":"钦佩者；赞赏者","ex":{"en":"He is a great admirer of Picasso's early paintings.","cn":"他十分赞赏毕加索的早期画作。"}},{"en":"a person who has a romantic or sexual interest in somebody","cn":"追求者；爱慕者","ex":{"en":"She never married but had many admirers.","cn":"她从未结婚，不过追求者不少。"}}]}},"adore":{"collins":{"senses":[{"pos":"VERB 动词","cn":"热爱；爱慕；敬慕；崇拜","en":"If you adore someone, you feel great love and admiration for them.","ex":{"en":"She adored her parents and would do anything to please them.","cn":"她很爱自己的父母，为让他们高兴愿意做任何事。"}},{"pos":"VERB 动词","cn":"热爱，喜爱(某事物）","en":"If you adore something, you like it very much.","ex":{"en":"My mother adores bananas and eats two a day","cn":"我妈妈非常喜欢吃香蕉，每天要吃两根。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to like someone very much and care a lot about them – used especially about people in your family or someone who you are sexually attracted to","cn":""},{"en":"to love and admire someone very much","cn":""},{"en":"to feel that you love someone and want to have a romantic relationship with them","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Someone you adore gets put on a pedestal. Considering your fear of germs, when you told me that you had shared a toothbrush — I knew you must adore her!"}]},"collocations":{"phrases":["ADV. absolutely, simply She absolutely adores her grandchildren. | clearly, obviously"]},"media":{"uk":"media/ldoce/hwd/bre/8/adore0205.mp3","us":"media/ldoce/hwd/ame/6/adore.mp3"},"examples":[{"en":"I simply adore his music!","cn":"我简直太喜爱他的音乐了！"},{"en":"It's obvious that she adores him.","cn":"她显然深深地爱着他。"}],"oxford":{"phon":"əˈdɔː(r)","pos":"verb","senses":[{"en":"to love somebody very much","cn":"热爱，爱慕（某人）","ex":{"en":"It's obvious that she adores him.","cn":"她显然深深地爱着他。"}},{"en":"to like something very much","cn":"喜爱，热爱（某事物）","lab":"informal","ex":{"en":"I simply adore his music!","cn":"我简直太喜爱他的音乐了！"}}]}},"addiction":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"毒瘾","en":"Addiction is the condition of taking harmful drugs and being unable to stop taking them.","ex":{"en":"She helped him fight his drug addiction.","cn":"她帮助他戒毒。"}},{"pos":"N-VAR 可变名词","cn":"着迷；嗜好","en":"An addiction to something is a very strong desire or need for it.","ex":{"en":"He needed money to feed his addiction to gambling","cn":"他需要钱来满足他的赌瘾。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an addiction to an illegal drug or to tobacco","cn":""},{"en":"addiction to alcohol or drugs, especially legal drugs that a doctor gives you, so that you feel you cannot continue to live without them","cn":""},{"en":"the need to take a harmful drug regularly, without being able to stop","cn":"瘾；毒瘾"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"An addiction is an abnormally strong craving for something, which can sometimes grow so strong you have trouble living without it."}]},"collocations":{"phrases":["ADJ. alcohol, cocaine, drug, etc.","VERB + ADDICTION become, turn into A habit can easily become an addiction. | have | cause, lead to | feed He stole money from his parents to","PREP. ~ to She had an addiction to heroin."]},"media":{"uk":"media/ldoce/hwd/bre/8/addiction0205.mp3","us":"media/ldoce/hwd/ame/c/addiction.mp3"},"examples":[{"en":"He is now fighting his addiction to alcohol.","cn":"他现在正努力戒酒。"},{"en":"cocaine addiction","cn":"可卡因瘾"}],"oxford":{"phon":"əˈdɪkʃn","pos":"noun","senses":[{"en":"the condition of being unable to stop using or doing something as a habit, especially something harmful","cn":"成瘾；上瘾","lab":"British English","ex":{"en":"cocaine addiction","cn":"可卡因瘾"}}]}},"administer":{"collins":{"senses":[{"pos":"VERB 动词","cn":"治理，管理（国家等）；施行，实施（法律、考核等）","en":"If someone administers something such as a country, the law, or a test, they take responsibility for organizing and supervising it.","ex":{"en":"The plan calls for the UN to administer the country until elections can be held","cn":"该方案呼吁联合国来管理该国，直到能进行选举为止。"}},{"pos":"VERB 动词","cn":"给予（病人药物）","en":"If a doctor or a nurse administers a drug, they give it to a patient.","ex":{"en":"Paramedics are trained to administer certain drugs.","cn":"护理人员们接受了配发某些药物的培训。"}},{"pos":"VERB 动词","cn":"给以（一拳或一脚）","en":"If someone administers a punch or a kick, they punch or kick someone.","ex":{"en":"He is shown in the tape of the beating as administering most of the blows.","cn":"录像显示在斗殴中他打得最凶。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to manage the work or money of a company or organization","cn":"管理﹐治理"},{"en":"to provide or organize something officially as part of your job","cn":"执行﹐实施﹔给予"},{"en":"to give someone a medicine or medical treatment","cn":"施用〔药物〕﹐给予〔治疗〕"}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"When you administer something, you give it to others. This can apply to a dose of medicine, an order, a survey, or a punishment. Administer can also mean to run something — such as a school or an office."}]},"collocations":{"phrases":["ADV. effectively, efficiently | centrally, locally The legislation was to be centrally administered by the Board of Education. | jointly","VERB + ADMINISTER be difficult/easy/simple to, be cheap/expensive to"]},"media":{"uk":"media/ldoce/hwd/bre/4/administer0205.mp3","us":"media/ldoce/hwd/ame/4/administer.mp3"},"examples":[{"en":"The questionnaire was administered by trained interviewers.","cn":"问卷调查是由经过训练的采访人员负责执行的。"},{"en":"Police believe his wife could not have administered the poison.","cn":"警方认为他的妻子是不可能下毒的。"}],"oxford":{"phon":"ədˈmɪnɪstə(r)","pos":"verb","senses":[{"en":"to manage and organize the affairs of a company, an organization, a country, etc.","cn":"管理（公司、组织、机构等）；治理（国家）","ex":{"en":"to administer a charity/fund/school","cn":"管理一家慈善机构／一项基金／一所学校"}},{"en":"to make sure that something is done fairly and in the correct way","cn":"施行；执行","ex":{"en":"to administer justice/the law","cn":"司法；执法"}},{"en":"to give or to provide something, especially in a formal way","cn":"给予；提供","lab":"formal","ex":{"en":"The teacher has the authority to administer punishment.","cn":"老师有权处罚。"}},{"en":"to give drugs, medicine, etc. to somebody","cn":"给予，施用（药物等）","lab":"formal","ex":{"en":"Police believe his wife could not have administered the poison.","cn":"警方认为他的妻子是不可能下毒的。"}},{"en":"to kick or to hit somebody/something","cn":"踢；打","lab":"formal","ex":{"en":"He administered a severe blow to his opponent's head.","cn":"他朝着对手的头部狠狠打了一拳。"}}]}},"adherence":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"坚持；遵守；遵循","en":"Adherence is the fact of adhering to a particular rule, agreement, or belief.","ex":{"en":"...strict adherence to the constitution.","cn":"严格遵守宪法"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone behaves according to a particular rule, belief, principle etc","cn":"坚持﹔信守"},{"en":"adherence to adherence to democratic principles","cn":"坚守民主的理念 strict/rigid/slavish adherence strict adherence to Judaic law 严格遵守犹太教教规"}]},"vocab":{"pos":"n","senses":[{"en":"Adherence means \"sticking to\" or \"being faithful to,\" such as your adherence to your diet even when chocolate cake is around, or students' adherence to school rules — they do not use cell phones or music players in class."}]},"collocations":{"phrases":["ADJ. blind, close, faithful, firm, rigid, slavish, strict","PREP. ~ to strict adherence to a diet"]},"media":{"uk":"media/ldoce/hwd/bre/2/adherence0205.mp3","us":"media/ldoce/hwd/ame/d/adherence.mp3"},"examples":[{"en":"strict adherence to the rules","cn":"严格遵守规章制度"}],"oxford":{"phon":"ədˈhɪərəns","pos":"noun","senses":[{"en":"the fact of behaving according to a particular rule, etc., or of following a particular set of beliefs, or a fixed way of doing something","cn":"坚持；遵守；遵循","ex":{"en":"strict adherence to the rules","cn":"严格遵守规章制度"}}]}},"adjacent":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"邻近的；毗连的","en":"If one thing is adjacent to another, the two things are next to each other.","ex":{"en":"He sat in an adjacent room and waited","cn":"他坐在隔壁房间里等候。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"the next room, house, street etc is the one immediately next to the one you are in","cn":""},{"en":"a building or piece of land that is adjacent to another one is immediately next to it","cn":""},{"en":"an adjoining room, building, or piece of land is one that is next to another one and is actually joined to it","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Adjacent means close to or near something. You may consider the people up and down your street to be neighbors, but your next door neighbor is the person who lives in the house or apartment adjacent to yours."}]},"collocations":{"phrases":["VERBS be, be situated, lie, stand The vineyards of Verzy lie adjacent to those of Verzenay.","ADJ. directly, immediately There is a row of houses immediately adjacent to the factory.","PREP. to The miller's house stands adjacent to the mill."]},"media":{"uk":"media/ldoce/hwd/bre/c/adjacent0205.mp3","us":"media/ldoce/hwd/ame/1/adjacent.mp3"},"examples":[{"en":"The planes landed on adjacent runways.","cn":"这些飞机在毗连的跑道上降落。"},{"en":"Our farm land was adjacent to the river.","cn":"我们的农田在河边。"}],"oxford":{"phon":"əˈdʒeɪsnt","pos":"adjective","senses":[{"en":"next to something","cn":"与…毗连的","ex":{"en":"The planes landed on adjacent runways.","cn":"这些飞机在毗连的跑道上降落。"}}]}},"adversity":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"厄运；逆境；困境","en":"Adversity is a very difficult or unfavourable situation.","ex":{"en":"He showed courage in adversity.","cn":"他在逆境中表现出了勇气。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"very unpleasant, painful, or upsetting conditions - use this especially about a situation that affects a lot of people","cn":""},{"en":"when your life is difficult and uncomfortable, especially because you are very poor","cn":""},{"en":"a difficult and unpleasant situation, in which people are suffering a lot and that makes you feel great sympathy for them","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When circumstances or situations work against you, you face adversity. Refugees from war-torn countries encounter terrible adversity ."}]},"collocations":{"phrases":["VERB + ADVERSITY be faced with, meet with When faced with adversity she was never tempted to give up. | overcome, triumph over","PREP. in ~ patience in adversity","PHRASES in the face of adversity courage in the face of adversity"]},"media":{"uk":"media/ldoce/hwd/bre/5/adversity0205.mp3","us":"media/ldoce/hwd/ame/9/adversity.mp3"},"examples":[{"en":"He overcame many personal adversities.","cn":"他克服了多次个人不幸。"},{"en":"courage in the face of adversity","cn":"面对逆境的勇气"}],"oxford":{"phon":"ədˈvɜːsəti","pos":"noun","senses":[{"en":"a difficult or unpleasant situation","cn":"困境；逆境","ex":{"en":"courage in the face of adversity","cn":"面对逆境的勇气"}}]}},"adolescent":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"青少年的;青春期的","en":"Adolescent is used to describe young people who are no longer children but who have not yet become adults. It also refers to their behaviour.","ex":{"en":"It is important that an adolescent boy should have an adult in whom he can confide","cn":"关键是，青春期的男孩身边应该有一个可以交心的成年人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is not yet an adult. You don’t usually use child to talk about babies or teenagers","cn":""},{"en":"a child. Kid is the usual word to use in everyday spoken English","cn":""},{"en":"a young male or female child","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"This is a fancy word for teenager. After puberty has begun but before adulthood is known as the adolescent phase."}]},"collocations":{"phrases":["ADJ. young | spotty | awkward, disturbed"]},"media":{"uk":"media/ldoce/hwd/bre/6/adolescent0205.mp3","us":"media/ldoce/hwd/ame/5/adolescent.mp3"},"examples":[{"en":"adolescents between the ages of 13 and 18 and the problems they face * 13","cn":"至 18 岁的青少年以及他们面临的问题"},{"en":"adolescent boys/girls/experiences","cn":"青春期的男孩/女孩/经历"}],"oxford":{"phon":"ˌædəˈlesnt","pos":"noun","senses":[{"en":"a young person who is developing from a child into an adult","cn":"青少年","ex":{"en":"adolescents between the ages of 13 and 18 and the problems they face","cn":"13 至 18 岁的青少年以及他们面临的问题"}},{"en":"in or relating to the process of developing from a child into an adult","cn":"青少年","ex":{"en":"adolescent boys/girls/experiences","cn":"青春期的男孩／女孩／经历"},"pos":"adjective"}]}},"adjustable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（位置或大小）可调整的","en":"If something is adjustable, it can be changed to different positions or sizes.","ex":{"en":"The bags have adjustable shoulder straps","cn":"这些包的肩带可以调整。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is adjustable can be changed or moved slightly to make it suitable for different purposes","cn":"可调整的﹐可调节的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's adjustable can be changed or altered so that it works or fits better. A car's adjustable seat can accommodate both very tall and very short drivers."}]},"collocations":{"phrases":["VERBS be","ADV. fully The straps are fully adjustable to fit any size."]},"media":{"uk":"media/ldoce/hwd/bre/c/adjustable0205.mp3","us":"media/ldoce/hwd/ame/7/laadadjustable.mp3"},"examples":[{"en":"The height of the bicycle seat is adjustable.","cn":"这辆自行车鞍座的高度可以调整。"},{"en":"adjustable seat belts","cn":"可调节的安全带"}],"oxford":{"phon":"əˈdʒʌstəbl","pos":"adjective","senses":[{"en":"that can be moved to different positions or changed in shape or size","cn":"可调整的；可调节的","ex":{"en":"adjustable seat belts","cn":"可调节的安全带"}}]}},"adaptation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（电影或电视的）改写本，改编本","en":"An adaptation of a book or play is a film or a television programme that is based on it.","ex":{"en":"...Branagh's screen adaptation of Shakespeare's Henry the Fifth.","cn":"布拉纳改编自莎士比亚的《亨利五世》的影片"}},{"pos":"N-UNCOUNT 不可数名词","cn":"适应;作出调整","en":"Adaptation is the act of changing something or changing your behaviour to make it suitable for a new purpose or situation.","ex":{"en":"Most living creatures are capable of adaptation when compelled to do so.","cn":"大多数生物都能在迫于压力的情况下适应新环境。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process of changing something from one form or system to another one so that it can be used for a different purpose","cn":""},{"en":"the process of changing something in particular ways so that it can be used for a different purpose","cn":""},{"en":"a film or television programme that is based on a book or play 〔","cn":"书或戏剧的〕改编版"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Some people always read the book before seeing the movie adaptation of it: They want to get the real story before it's rewritten for film and imagine what all the characters look like before the wrong actors are chosen to play them."}]},"collocations":{"phrases":["ADJ. successful | special","VERB + ADAPTATION make making adaptations to your home","ADAPTATION + VERB occur Adaptations in plants occur over thousands of years.","PREP. ~ for The Antarctic species have few special adaptations for polar life. | ~ to adaptation to the workplace","PHRASES a process of adaptation The process of adaptation to a new school is difficult for some children. 2 film, TV programme","ADJ. film, screen, television/TV He specializes in screen adaptations of classic novels.","VERB + ADAPTATION film, make, produce"]},"media":{"uk":"media/ldoce/hwd/bre/d/adaptation0205.mp3","us":"media/ldoce/hwd/ame/2/adaptation.mp3"},"examples":[{"en":"a screen adaptation of Shakespeare's ‘Macbeth’","cn":"莎士比亚悲剧《麦克白》的电影改写本"},{"en":"the adaptation of desert species to the hot conditions","cn":"沙漠物种对炎热环境的适应"}],"oxford":{"phon":"ˌædæpˈteɪʃn","pos":"noun","senses":[{"en":"the action or process of changing something, or of being changed, to suit a new purpose or situation","cn":"适应","g":"[uncountable, countable]","ex":{"en":"the adaptation of buildings for military purposes","cn":"出于军事目的对建筑进行的改造"}},{"en":"a film, television drama or play that is based on a particular book or play but has been changed to suit the new medium","cn":"改编本；改写本","g":"[countable]","ex":{"en":"a screen adaptation of Shakespeare’s ‘Macbeth’","cn":"莎士比亚悲剧《麦克白》的电影改写本"}},{"en":"the process of change by which a species becomes better suited to its environment","cn":"（物种对环境的）适应","g":"[uncountable, countable]","lab":"biology","ex":{"en":"the adaptation of desert species to the hot conditions","cn":"沙漠物种对炎热环境的适应"}}]}},"adulthood":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"成年","en":"Adulthood is the state of being an adult.","ex":{"en":"Few people nowadays are able to maintain friendships into adulthood.","cn":"如今很少有人能将友谊维持到成年。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of someone's life when they are an adult","cn":""},{"en":"the time when someone is an adult - use this especially to talk about people reaching this time","cn":""},{"en":"if a person, animal, or plant reaches maturity , they have grown or developed completely","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When you stop growing and start shaving, you are in adulthood — a point where you reach maturity. Unfortunately, physical adulthood does not necessarily imply that psychological adulthood is present."}]},"collocations":{"phrases":["ADJ. early, young","VERB + ADULTHOOD attain, reach children who lose their parents before reaching adulthood | make it to, survive into/to","PREP. during/in ~ His problems began in early adulthood. | into ~ Her childhood problems persisted into adulthood. | towards ~ a step toward"]},"media":{"uk":"media/ldoce/hwd/bre/e/adulthood0703.mp3","us":"media/ldoce/hwd/ame/7/laadadulthood.mp3"},"examples":[{"en":"a child reaching adulthood","cn":"已成年的孩子"}],"oxford":{"phon":"ˈædʌlthʊd","pos":"noun","senses":[{"en":"the state of being an adult","cn":"成年","ex":{"en":"a child reaching adulthood","cn":"已成年的孩子"}}]}},"admirable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人钦佩的；值得赞赏的","en":"An admirable quality or action is one that deserves to be praised and admired.","ex":{"en":"Beyton is an admirable character","cn":"贝顿是个令人钦佩的人物。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely good","cn":""},{"en":"an outstanding performance or achievement is extremely good and much better than that of most other people","cn":""},{"en":"extremely good, and showing an unusually high level of skill or intelligence","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Someone who deserves your admiration can be described as admirable . Your friend who saves homeless kittens in his spare time? An admirable person."}]},"collocations":{"phrases":["VERBS be | find sb/sth","ADV. very | wholly She had acted in ways that he found wholly admirable. | truly"]},"media":{"uk":"media/ldoce/hwd/bre/a/admirable0205.mp3","us":"media/ldoce/hwd/ame/8/admirable.mp3"},"examples":[{"en":"Her dedication to her work was admirable.","cn":"她对工作的奉献精神可钦可佩。"},{"en":"He made his points with admirable clarity.","cn":"他阐述观点明确，值得赞赏。"}],"oxford":{"phon":"ˈædmərəbl","pos":"adjective","senses":[{"en":"having qualities that you admire and respect","cn":"可钦佩的；值得赞赏的；令人羡慕的","ex":{"en":"Her dedication to her work was admirable.","cn":"她对工作的奉献精神可钦可佩。"}}]}},"advert":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"广告","en":"An advert is an announcement in a newspaper, on television, or on a poster about something such as a product, event, or job.","ex":{"en":"I saw an advert for a job with a large engineering company","cn":"我看见一家大型工程公司的招聘广告。"}},{"pos":"N-COUNT 可数名词","cn":"广告；宣传","en":"If you say that an example of something is an advert for that thing in general, you mean that it shows how good that thing is.","ex":{"en":"This courtroom battle has been a poor advert for English justice.","cn":"这场法庭上的争论为英格兰的司法制度做了一次拙劣的广告。"}},{"pos":"N-PLURAL 复数名词","cn":"（电视上的）广告时间","en":"You can use the adverts to refer to the interval in a commercial television programme, or between programmes, during which advertisements are shown.","ex":{"en":"After the adverts, the presenter tried to pretend that everything was back to normal.","cn":"广告过后，主持人努力假装一切恢复正常。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an advertisement","cn":"广告"},{"en":"an advertisement","cn":"广告"},{"en":"an advertisement on television or radio","cn":""}]},"vocab":{"pos":"1 v 2 n","senses":[{"en":"This one's easy. An advert is an advertisement: just shorten advertisement , and you get advert . Of course, as a verb, to advert to something means to refer to it."}]},"collocations":{"phrases":["ADJ. classified, front-page, full-page | magazine, newspaper, television/TV | chocolate, job, etc.","VERB + ADVERT place, put, take out I put an advert in the local newspaper. She took out a full-page advert in a magazine. | carry, publish, ","ADVERT + VERB appear The advert appeared in &lsquo;The Guardian&rsquo;. | say sth, show sth, state sth | feature sb/sth The advert featured ","PREP. in a/the ~ A lot of claims are made in the advert. | ~ for an advert for jeans"]},"media":{"uk":"media/ldoce/hwd/bre/e/advert_n0205.mp3","us":"media/ldoce/hwd/ame/c/ld44advert.mp3"},"examples":[{"en":"When the adverts came on I got up to put the kettle on.","cn":"电视播放广告时，我起身去烧了壶水。"},{"en":"the adverts on television","cn":"电视广告"}],"oxford":{"phon":"ˈædvɜːt","pos":"noun","senses":[{"en":"a notice, picture or film telling people about a product, job or service","cn":"广告；启事","lab":"informal","ex":{"en":"the adverts on television","cn":"电视广告"}},{"en":"an example of something that shows its good qualities","cn":"广告（样）品"}]}},"adultery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"通奸；婚外性行为","en":"If a married person commits adultery, they have sex with someone that they are not married to.","ex":{"en":"She is going to divorce him on the grounds of adultery.","cn":"她以丈夫搞婚外情为由要求离婚。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if someone is unfaithful , they have sex with someone who is not their husband, girlfriend etc","cn":""},{"en":"if someone cheats on their husband, girlfriend etc, they secretly have sex with someone else","cn":""},{"en":"a secret sexual relationship between two people when at least one of them is married to someone else","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Adultery is a word for cheating — cheating on your spouse with another person. Adultery isn’t a crime, but some people consider it a sin."}]},"collocations":{"phrases":["VERB + ADULTERY be guilty of, commit | accuse sb of | admit","PREP. ~ with He admitted adultery with several women."]},"media":{"uk":"media/ldoce/hwd/bre/b/adultery0205.mp3","us":"media/ldoce/hwd/ame/b/adultery.mp3"},"examples":[{"en":"He was accused of committing adultery.","cn":"他被控通奸。"},{"en":"an adulterous relationship","cn":"通奸关系"}],"oxford":{"phon":"əˈdʌltəri","pos":"noun","senses":[{"en":"sex between a married person and somebody who is not their husband or wife","cn":"通奸","ex":{"en":"He was accused of committing adultery.","cn":"他被控通奸。"}}]}},"adrenalin":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"肾上腺素（情绪激动时肾上腺分泌的一种化学物质，能加快心跳及产生更多能量）","en":"Adrenalin is a substance which your body produces when you are angry, scared, or excited. It makes your heart beat faster and gives you more energy.","ex":{"en":"Seeing the crowd really got my adrenalin pumping.","cn":"看见这么多人确实让我热血沸腾。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a chemical produced by your body when you are afraid, angry, or excited, which makes your heart beat faster","cn":"肾上腺素"}]},"collocations":{"phrases":["ADJ. pure","QUANT. burst, flow, rush, surge He felt a surge of pure adrenalin as he won the race.","VERB + ADRENALIN feel","ADRENALIN + VERB course, flow, pump, surge The adrenalin was coursing through his system.","ADRENALIN + NOUN rush","PHRASES get the adrenalin flowing/going We'll start with a bit of dancing to get the adrenalin going."]},"media":{"uk":"media/ldoce/hwd/bre/8/adrenalin0205.mp3","us":"media/ldoce/hwd/ame/c/amelasdeadrenalin.mp3"},"examples":[{"en":"There’s nothing like a good horror film to get the adrenalin going (= make you feel nervously excited ) .","cn":"好的恐怖片最能让人看得血脉偾张。"}]},"adrift":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"漂浮着的;漂流着的","en":"If a boat is adrift, it is floating on the water and is not tied to anything or controlled by anyone.","ex":{"en":"They were spotted after three hours adrift in a dinghy.","cn":"他们在小舢板上漂浮了3个小时后才被发现。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"茫然的；无所适从的","en":"If someone is adrift, they feel alone with no clear idea of what they should do.","ex":{"en":"Amy had the growing sense that she was adrift and isolated.","cn":"埃米愈发感到自己孤立无援，孑然一身。"}},{"pos":"ADJ 形容词","cn":"脱落的；脱开的","en":"If something comes adrift, it is no longer attached to an object that it should be part of.","ex":{"en":"Three insulating panels had come adrift from the base of the vehicle.","cn":"车子底盘的3块隔热板已经脱落了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"分数落后的;排名在后的","en":"In sporting competitions, if a team or a player is adrift of their rivals, they are behind them, usually by a specified number of points or by a specified distance.","ex":{"en":"Aberdeen are nine points adrift of Rangers at the top of the Scottish League.","cn":"在苏格兰足球联赛中，亚伯丁队比排在首位的流浪者队落后9分。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"出了问题的","en":"If something has gone adrift, it is no longer happening in the way that was intended.","ex":{"en":"We have seen this as an attempt to place the blame for a policy that has gone adrift.","cn":"我们已经认识到，这是把责任归咎于一项已偏离方向的政策的一种企图。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a boat that is adrift is not fastened to anything or controlled by anyone","cn":"漂浮着（的）﹐漂流着（的）"},{"en":"someone who is adrift is confused about what to do in their life","cn":"漫无目标的[地]"},{"en":"if something comes adrift, it is no longer fastened or attached to something","cn":"散开﹔脱落"}]},"vocab":{"pos":"adj adv","senses":[{"en":"If something's adrift , it's floating, not tied down or anchored. A raft that's adrift on a river will float downstream."}]},"collocations":{"phrases":["VERBS be | come I nearly suffocated when the pipe of my breathing apparatus came adrift. | cast sb/sth, cut sb/sth, set sb/sth Their boat ha","PREP. from (figurative) She had been cut adrift from everything she had known. | in (figurative) cast adrift in a vulgar, materialistic soci"]},"media":{"uk":"media/ldoce/hwd/bre/1/adrift0205.mp3","us":"media/ldoce/hwd/ame/f/adrift.mp3"},"examples":[{"en":"I nearly suffocated when the pipe on my breathing apparatus came adrift.","cn":"我的呼吸器上的管子脱落时，我差一点窒息。"},{"en":"The team are now just six points adrift of the leaders.","cn":"现在该队得分比领先的队只落后六分。"}],"oxford":{"phon":"əˈdrɪft","pos":"adjective","senses":[{"en":"if a boat or a person in a boat is adrift, the boat is not tied to anything or is floating without being controlled by anyone","cn":"漂浮；漂流","ex":{"en":"The survivors were adrift in a lifeboat for six days.","cn":"幸存者在救生艇上漂流了六天。"}},{"en":"feeling alone and without a direction or an aim in life","cn":"漫无目的；随波逐流；漂泊无依","ex":{"en":"young people adrift in the big city","cn":"在大城市四处漂泊的年轻人"}},{"en":"no longer attached or fixed in the right position","cn":"脱开；松开","lab":"figurative","ex":{"en":"I nearly suffocated when the pipe on my breathing apparatus came adrift.","cn":"我的呼吸器上的管子脱落时，我差一点窒息。"}},{"en":"behind the score or position of your opponents","cn":"分数落后；排名在后","lab":"especially British English","ex":{"en":"The team are now just six points adrift of the leaders.","cn":"现在该队得分比领先的队只落后六分。"}}]}},"admiral":{"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"海军上将;海军将军;舰队司令","en":"An admiral is a very senior officer who commands a navy.","ex":{"en":"...Admiral Hodges.","cn":"海军上将霍奇斯"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a high rank in the British or US navy, or someone with this rank 〔","cn":"英国或美国的〕海军上将"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"An admiral is the commander of a fleet. In the navy, admiral is one of the highest ranks."}]},"collocations":{"phrases":["ADJ. rear, vice • Note at RANK"]},"media":{"uk":"media/ldoce/hwd/bre/1/admiral0205.mp3","us":"media/ldoce/hwd/ame/7/admiral.mp3"},"examples":[{"en":"The admiral visited the ships under his command.","cn":"舰队司令视察了他所统率的军舰。"},{"en":"Admiral Lord Nelson","cn":"海军上将纳尔逊勋爵"}],"oxford":{"phon":"ˈædmərəl","pos":"noun","senses":[{"en":"an officer of very high rank in the navy","cn":"海军将官；海军上将；舰队司令","ex":{"en":"The admiral visited the ships under his command.","cn":"舰队司令视察了他所统率的军舰。"}}]}},"admittance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"准许进入；进入权","en":"Admittance is the act of entering a place or institution or the right to enter it.","ex":{"en":"We had not been able to gain admittance to the flat.","cn":"我们未能获准进入公寓。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"permission to enter a place","cn":"进入权"}]},"collocations":{"phrases":["VERB + ADMITTANCE gain They were unable to gain admittance to the hall. | allow sb | deny sb, refuse sb","PREP. ~ to The ticket will allow you admittance to the theatre."]},"media":{"uk":"media/ldoce/hwd/bre/e/admittance0205.mp3","us":"media/ldoce/hwd/ame/5/admittance.mp3"},"examples":[{"en":"Hundreds of people were unable to gain admittance to the hall.","cn":"数以百计的人未能获准进入大厅。"},{"en":"Gaining admittance to the club was no easy matter.","cn":"获准进入那家俱乐部并非易事。"}],"oxford":{"phon":"ədˈmɪtns","pos":"noun","senses":[{"en":"the right to enter or the act of entering a building, an institution, etc.","cn":"（建筑物、机构等的）进入权，进入","ex":{"en":"Hundreds of people were unable to gain admittance to the hall.","cn":"数以百计的人未能获准进入大厅。"}}]}},"adviser":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"顾问；提供意见者","en":"An adviser is an expert whose job is to give advice to another person or to a group of people.","ex":{"en":"In Washington, the President and his advisers spent the day in meetings.","cn":"在华盛顿，总统和他的顾问们一整天都在开会。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to give advice, especially in business, law, or politics","cn":""},{"en":"someone who gives special technical advice to companies or other organizations","cn":""},{"en":"someone who gives professional advice and emotional support to people, especially about personal problems","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you're an expert who gives advice or offers professional consultations, you can call yourself an adviser ."}]},"collocations":{"phrases":["ADJ. chief, lead, principal, senior, special the government's chief medical adviser | close, trusted The duke was the king's most trusted ad","VERB + ADVISER act as | appoint, appoint sb (as) | have Do you have a financial adviser? | consult (with), go to, see, speak to, talk to You","ADVISER + VERB advise sb/sth","PREP. ~ on an adviser on environmental issues | ~ to She acts as an adviser to the president."]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdeadviser.mp3","us":"media/ldoce/hwd/ame/1/laadadviser.mp3"},"examples":[{"en":"a special adviser to the President on education","cn":"总统的教育特别顾问"},{"en":"a financial adviser","cn":"财务顾问"}],"oxford":{"phon":"ədˈvaɪzə(r)","pos":"noun","senses":[{"en":"a person who gives advice, especially somebody who knows a lot about a particular subject","cn":"顾问；忠告者；提供意见者","ex":{"en":"a financial adviser","cn":"财务顾问"}}]}},"adaptable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有适应能力的;能适应的;适应性强的","en":"If you describe a person or animal as adaptable, you mean that they are able to change their ideas or behaviour in order to deal with new situations.","ex":{"en":"...a more adaptable and skilled workforce","cn":"一支适应能力及技能更强的劳动大军"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"methods, systems, or rules that are flexible can easily be changed if necessary","cn":""},{"en":"a system or way of doing something that is adaptable can be changed so that it is suitable for very different uses and very different situations","cn":""},{"en":"willing to change your ideas, plans, or methods according to the situation","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that is adaptable can change to fit its environment, whether that environment is natural or social. The level to which a species is adaptable to changing surroundings is an important factor in the study of evolution."}]},"collocations":{"phrases":["VERBS be, prove | become | make sb/sth","ADV. highly, very Many old market buildings have proved highly adaptable. | fairly, quite | easily, readily","PREP. to The vehicles are large and not easily adaptable to new uses."]},"media":{"uk":"media/ldoce/hwd/bre/a/adaptable0205.mp3","us":"media/ldoce/hwd/ame/8/adaptable.mp3"},"examples":[{"en":"Older workers can be as adaptable and quick to learn as anyone else.","cn":"较年长的工人的适应能力和学习速度有时并不亚于其他任何人。"},{"en":"Successful businesses are highly adaptable to economic change.","cn":"成功的企业对于经济转变的适应能力很强。"}],"oxford":{"phon":"əˈdæptəbl","pos":"adjective","senses":[{"en":"able to change or be changed in order to deal successfully with new situations","cn":"有适应能力的；能适应的","ex":{"en":"Older workers can be as adaptable and quick to learn as anyone else.","cn":"较年长的工人的适应能力和学习速度有时并不亚于其他任何人。"}}]}},"adjourn":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"休（会）；休（庭）","en":"If a meeting or trial is adjourned or if it adjourns, it is stopped for a short time.","ex":{"en":"The proceedings have now been adjourned until next week","cn":"会议休会至下周重开。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to stop speaking or stop doing something for a very short time before starting again. Pause is used especially in written descriptions. In everyday spoken English, people usually just say stop","cn":""},{"en":"to stop for a moment and wait before doing something, because you feel unsure or nervous about it","cn":""},{"en":"to stop working for a short time in order to rest, eat etc","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To adjourn is to close a session of something, like at court. People also adjourn when they go to bed."}]},"collocations":{"phrases":["ADV. indefinitely The trial was adjourned indefinitely.","PREP. for At midday the meeting was adjourned for lunch. | pending The inquest was adjourned pending further investigations. | to Shall we a"]},"media":{"uk":"media/ldoce/hwd/bre/1/adjourn0205.mp3","us":"media/ldoce/hwd/ame/f/adjourn.mp3"},"examples":[{"en":"The judge granted us a short adjournment.","cn":"法官允许我们暂时休庭。"},{"en":"The court adjourned for lunch.","cn":"午餐时间法庭休庭。"}],"oxford":{"phon":"əˈdʒɜːn","pos":"verb","senses":[{"en":"to stop a meeting or an official process, especially a trial, for a period of time","cn":"休庭；休会；延期","ex":{"en":"The court adjourned for lunch.","cn":"午餐时间法庭休庭。"}}]}},"advisor":{"vocab":{"pos":"n","senses":[{"en":"An advisor is a person who gives advice or leads a group, like an advisor to the school yearbook club, guiding its members in putting together the pages, but not doing the work for them."}]}}});
